
(()=>{'use strict';const D=window.COURSE_DATA,DICT=window.COURSE_DICTIONARY,P=window.ADMIN_PROMPTS,C=window.APP_CONFIG;const SKEY='ep-state-v1',PACKKEY='ep-content-packs-v1',DB='ep-audio-v1',STORE='audio';applyContentPacks();const $=id=>document.getElementById(id);const screen=$('screen'),drawer=$('drawer'),popup=$('popup'),modal=$('modal'),toast=$('toast');let state=load(),view='dashboard',selection=state.level||'A1',admin=false,exam=null,timer=null;
function fresh(){return{onboarded:false,profile:{name:'',email:'',purpose:'General English',nativeLanguage:'',country:'',goal:'',interests:'',englishPreference:'British English',dailyMinutes:30,avatar:''},level:'A1',unlocked:['A1'],current:'A1-U1-D1',progress:{},vocab:[],notes:{},exams:{},theme:'light',wordHelp:true,soundEffects:true,endpoint:C.teacherEndpoint||'',recommendation:null,activity:[],sync:{enabled:false,email:'',auth:'',lastSyncAt:null,lastStatus:'Not connected'}}}
function contentPacks(){try{const a=JSON.parse(localStorage.getItem(PACKKEY)||'[]');return Array.isArray(a)?a:[]}catch(e){return[]}}
function applyContentPacks(){for(const pack of contentPacks()){if(pack?.platform!=='English Pathways')continue;for(const item of(pack.addedUnits||[])){const l=D.levels.find(x=>x.id===item.levelId);if(!l)continue;const ids=new Set(l.units.map(u=>u.id));for(const u of(item.units||[])){if(!ids.has(u.id)){l.units.push(u);ids.add(u.id)}}l.units.sort((a,b)=>(a.number||0)-(b.number||0))}for(const item of(pack.replaceUnits||[])){const l=D.levels.find(x=>x.id===item.levelId);if(!l)continue;for(const u of(item.units||[])){const i=l.units.findIndex(x=>x.id===u.id);if(i>=0)l.units[i]=u;else l.units.push(u)}l.units.sort((a,b)=>(a.number||0)-(b.number||0))}if(pack.dictionary&&typeof pack.dictionary==='object')Object.assign(DICT,pack.dictionary)}D.lessonCount=D.levels.reduce((n,l)=>n+l.units.reduce((m,u)=>m+u.lessons.length,0),0)}
function compareVersions(a,b){const pa=String(a||'0').split('.').map(Number),pb=String(b||'0').split('.').map(Number);for(let i=0;i<Math.max(pa.length,pb.length);i++){const x=pa[i]||0,y=pb[i]||0;if(x>y)return 1;if(x<y)return-1}return 0}
function load(){try{const base=fresh(),raw=JSON.parse(localStorage.getItem(SKEY)||'null')||{};const s={...base,...raw,profile:{...base.profile,...(raw.profile||{})},sync:{...base.sync,...(raw.sync||{})}};if(!s.endpoint&&C.teacherEndpoint)s.endpoint=C.teacherEndpoint;return s}catch(e){return fresh()}}let syncSuspend=false,syncDebounce=null;function save(){localStorage.setItem(SKEY,JSON.stringify(state));localStorage.setItem('ep-sound-effects',state.soundEffects===false?'off':'on');if(!syncSuspend&&state.sync?.enabled&&state.sync?.auth)queueCloudSync()}function esc(s=''){return String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}function say(m){toast.textContent=m;toast.classList.add('show');clearTimeout(say.t);say.t=setTimeout(()=>toast.classList.remove('show'),2300)}function log(t,d={}){state.activity.push({t,d,at:new Date().toISOString()});save()}function level(id){return D.levels.find(x=>x.id===id)||D.levels[0]}function idx(id){return D.levels.findIndex(x=>x.id===id)}function lessons(id=null){return(id?[level(id)]:D.levels).flatMap(l=>l.units.flatMap(u=>u.lessons.map(x=>({...x,levelId:l.id,unitTitle:u.title}))))}function findLesson(id){return lessons().find(x=>x.id===id)||lessons()[0]}function lp(id){if(!state.progress[id])state.progress[id]={done:false,quiz:{},writing:'',homework:'',step:0};return state.progress[id]}function prog(id){const a=lessons(id),n=a.filter(x=>state.progress[x.id]?.done).length;return{n,total:a.length,p:a.length?Math.round(n/a.length*100):0}}function unlocked(id){return state.unlocked.includes(id)}function words(s){return String(s).trim()?String(s).trim().split(/\s+/).length:0}function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},800)}function safe(s){return String(s||'student').replace(/[^a-z0-9_-]+/gi,'_')}function theme(){document.documentElement.dataset.theme=state.theme}theme();
$('homeBtn')&&($('homeBtn').onclick=()=>go('dashboard'));$('desktopHomeBtn')&&($('desktopHomeBtn').onclick=()=>go('dashboard'));$('courseBtn')&&($('courseBtn').onclick=()=>go('course'));$('practiceBtn')&&($('practiceBtn').onclick=()=>go('practice'));$('progressBtn')&&($('progressBtn').onclick=()=>go('progress'));$('profileBtn')&&($('profileBtn').onclick=()=>go('profile'));$('moreBtn')&&($('moreBtn').onclick=()=>go('more'));$('adminBtn')&&($('adminBtn').onclick=gate);$('themeBtn')&&($('themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';theme();save()});
function announceView(v){document.body.dataset.view=v;window.dispatchEvent(new CustomEvent('ep:viewchange',{detail:{view:v}}))}function go(v,p={}){clearInterval(timer);view=v;announceView(v);drawer.classList.remove('open');popup.hidden=true;if(v==='dashboard')dashboard();if(v==='course'){if(p.level)selection=p.level;course()}if(v==='practice')practiceView();if(v==='lesson')lessonView(p.id||state.current);if(v==='vocab')vocabView();if(v==='progress')progressView();if(v==='profile')profileView();if(v==='more')moreView();if(v==='exam')examStart(p.level||state.level);if(v==='updates')updatesView();if(v==='admin')adminView(p.tab||'overview')}
function render(){state.onboarded?go('dashboard'):onboard()}
function onboard(){announceView('onboard');const gateway=Boolean(gatewayEndpoint());screen.innerHTML=`<div class="shell"><section class="hero onboardingHero"><div class="eyebrow">Complete English pathway</div><h1>Learn every day and keep every result.</h1><p class="lead">Create a student profile, or restore an existing profile on a new device.</p><div class="onboardGrid"><form id="form" class="formgrid profileForm"><div class="full"><h2>New student profile</h2></div><div class="field"><label>Name</label><input id="name" required autocomplete="name"></div><div class="field"><label>Email</label><input id="email" type="email" autocomplete="email"></div>${gateway?`<div class="field"><label>Private sync PIN</label><input id="newSyncPin" type="password" inputmode="numeric" autocomplete="new-password" placeholder="6+ characters for cross-device restore"><small>Use the same email + PIN on another device.</small></div>`:''}<div class="field"><label>Starting level</label><select id="start">${D.levels.map(l=>`<option value="${l.id}">${l.cefr} — ${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Purpose</label><select id="purpose"><option>General English</option><option>Employment</option><option>Teaching</option><option>Academic study</option></select></div><div class="full notice">Placement is optional. Your teacher can recommend or change the starting level later.</div><div class="full"><button class="primary">Create profile</button></div></form><div class="restoreCard"><div class="eyebrow">Already studied here?</div><h2>Restore on this device</h2><p>Use the same email and your private sync PIN. Email alone is not enough because anyone who knows an email address must not be able to open another student's progress.</p><div class="field"><label>Email</label><input id="restoreEmail" type="email" autocomplete="email"></div><div class="field"><label>Private sync PIN</label><input id="restorePin" type="password" inputmode="numeric" autocomplete="current-password" placeholder="6 or more characters"></div><button class="secondary" id="restoreCloud" ${gateway?'':'disabled'}>Restore profile and progress</button>${gateway?'':'<div class="notice warn" style="margin-top:12px">Cloud restore becomes available after the Gateway v2 update is deployed.</div>'}</div></div></section></div>`;document.getElementById('form').onsubmit=async e=>{e.preventDefault();const email=$('email').value.trim(),pin=$('newSyncPin')?.value||'';if(pin&&pin.length<6)return say('Use at least 6 characters for the sync PIN.');state.profile={...fresh().profile,name:$('name').value.trim(),email,purpose:$('purpose').value};state.level=$('start').value;state.unlocked=D.levels.slice(0,idx(state.level)+1).map(l=>l.id);state.current=level(state.level).units[0].lessons[0].id;state.onboarded=true;save();if(gateway&&email&&pin){try{await connectCloud(email,pin);say('Profile created and cloud sync connected.')}catch(err){say('Profile created. Cloud sync needs attention: '+(err.message||err))}}dashboard()};$('restoreCloud').onclick=async()=>{const email=$('restoreEmail').value.trim(),pin=$('restorePin').value.trim();if(!email||pin.length<6)return say('Enter the account email and a PIN of at least 6 characters.');$('restoreCloud').disabled=true;$('restoreCloud').textContent='Restoring…';try{await restoreCloudAccount(email,pin);say('Progress restored.');setTimeout(()=>dashboard(),350)}catch(err){say('Restore failed: '+(err.message||err));$('restoreCloud').disabled=false;$('restoreCloud').textContent='Restore profile and progress'}}}
function dashboard(){announceView('dashboard');const l=level(state.level),p=prog(l.id),cur=findLesson(state.current),avatar=avatarHtml(state.profile,'large');screen.innerHTML=`<div class="shell"><section class="hero dashboardHero"><div class="dashboardIdentity">${avatar}<div><div class="eyebrow">Welcome back, ${esc(state.profile.name||'learner')}</div><h1>Your English pathway continues here.</h1><p class="lead">${esc(l.description)}</p></div></div><div class="buttons"><button class="primary" id="continue">Continue: ${esc(cur.title)}</button><button class="secondary" id="browse">Browse course</button><button class="ghost" id="placement">Placement test</button></div></section><div class="metrics"><div class="metric"><small>Current level</small><strong>${l.cefr}</strong></div><div class="metric"><small>Course progress</small><strong>${p.p}%</strong></div><div class="metric"><small>Lessons complete</small><strong>${p.n}/${p.total}</strong></div><div class="metric"><small>Saved words</small><strong>${state.vocab.length}</strong></div></div><div class="grid2"><section class="card"><h2>Daily routine</h2><div class="grid3" style="margin-top:15px"><div class="notice"><b>Review</b><br><small>Previous errors and vocabulary</small></div><div class="notice"><b>Learn</b><br><small>Grammar, reading or listening</small></div><div class="notice"><b>Produce</b><br><small>Speaking, writing and quiz</small></div></div><div class="progress" style="margin-top:18px"><div style="width:${p.p}%"></div></div>${state.sync?.enabled?`<div class="syncMini">☁ ${esc(state.sync.lastStatus||'Cloud sync connected')}${state.sync.lastSyncAt?` • ${new Date(state.sync.lastSyncAt).toLocaleString()}`:''}</div>`:''}</section><section class="card"><h2>Quick tools</h2><div class="sideList"><button class="sideItem" id="qp">Student profile & sync</button><button class="sideItem" id="qd">Dictionary and Word Help</button><button class="sideItem" id="qv">Vocabulary notebook</button><button class="sideItem" id="qe">End-of-level exam</button><button class="sideItem" id="qu">Install course update</button><button class="sideItem" id="qb">Export progress backup</button></div></section></div></div>`;$('continue').onclick=()=>go('lesson',{id:state.current});$('browse').onclick=()=>go('course');$('placement').onclick=()=>window.open('placement-test/index.html','_blank');$('qp').onclick=()=>go('profile');$('qd').onclick=openDictionary;$('qv').onclick=()=>go('vocab');$('qe').onclick=()=>go('exam',{level:state.level});$('qu').onclick=()=>go('updates');$('qb').onclick=exportBackup}
function course(){announceView('course');const l=level(selection);screen.innerHTML=`<div class="shell"><div class="courseLayout"><aside class="sidebar"><div class="eyebrow">Course levels</div><div class="sideList">${D.levels.map(x=>`<button class="sideItem ${x.id===selection?'active':''}" data-level="${x.id}">${x.cefr} — ${esc(x.name)} ${unlocked(x.id)?'':'• Preview'}</button>`).join('')}</div></aside><div><section class="hero"><div class="eyebrow">${l.cefr} course</div><h1>${esc(l.name)}</h1><p class="lead">${esc(l.description)}</p><div class="metrics"><div class="metric"><small>Units</small><strong>${l.units.length}</strong></div><div class="metric"><small>Lessons</small><strong>${lessons(l.id).length}</strong></div><div class="metric"><small>Progress</small><strong>${prog(l.id).p}%</strong></div><div class="metric"><small>Status</small><strong style="font-size:16px">${unlocked(l.id)?'Open':'Preview'}</strong></div></div></section><div style="margin-top:16px">${l.units.map(u=>`<section class="unit"><div class="unitHead richUnitHead"><div><div class="eyebrow">Unit ${u.number}</div><h2>${esc(u.title)}</h2><small>${esc(u.theme)}</small><p class="unitTopic">${esc(u.topicTitle||"")}</p></div>${u.illustration?`<img class="unitThumb" src="${esc(u.illustration)}" alt="Illustration for ${esc(u.topicTitle||u.title)}">`:""}</div>${u.lessons.map((x,i)=>{const p=lp(x.id),open=unlocked(l.id)||i===0;return`<div class="lessonRow ${p.done?'done':''}"><div class="num">${p.done?'✓':x.day}</div><div><b>${esc(x.title)}</b><br><small>${x.minutes} min • ${esc(x.subtitle)}</small></div><button class="${open?'secondary':'ghost'}" data-lesson="${x.id}" ${open?'':'disabled'}>${p.done?'Review':'Open'}</button></div>`}).join('')}</section>`).join('')}<div class="buttons"><button class="primary" id="examBtn">Open ${l.cefr} end-of-level exam</button></div></div></div></div></div>`;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{selection=b.dataset.level;course()});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>go('lesson',{id:b.dataset.lesson}));$('examBtn').onclick=()=>go('exam',{level:l.id})}
function practiceView(){announceView('practice');const x=findLesson(state.current),p=lp(x.id),l=level(state.level);screen.innerHTML=`<div class="shell"><section class="hero practiceHero"><div class="eyebrow">Practice hub</div><h1>Turn today’s English into a skill.</h1><p class="lead">Choose a focused practice route. Your current lesson is <b>${esc(x.title)}</b>.</p><div class="practiceHeroActions"><button class="primary" id="practiceCurrent">Continue lesson practice</button><button class="secondary" id="practiceUse">Go to speaking / writing</button></div></section><div class="practiceGrid"><button class="practiceTile" id="practiceWords"><span class="practiceIcon">Aa</span><div><b>Vocabulary retrieval</b><small>Review saved words, meanings and pronunciation.</small></div></button><button class="practiceTile" id="practiceDictionary"><span class="practiceIcon">⌕</span><div><b>Dictionary & Word Help</b><small>Look up course vocabulary without leaving the lesson flow.</small></div></button><button class="practiceTile" id="practiceExam"><span class="practiceIcon">✓</span><div><b>${esc(l.cefr)} checkpoint</b><small>Open the end-of-level assessment when you are ready.</small></div></button><button class="practiceTile" id="practicePlacement"><span class="practiceIcon">↗</span><div><b>Placement test</b><small>Open or continue the comprehensive placement assessment.</small></div></button></div><section class="card practiceAdvice"><div class="eyebrow">Better practice</div><h2>Use a short cycle</h2><div class="practiceCycle"><span><b>1</b> Retrieve</span><span><b>2</b> Use</span><span><b>3</b> Check</span><span><b>4</b> Improve</span></div><p>Do not repeat an answer without a goal. Recall the idea, use it in context, check feedback, then improve one specific feature.</p></section></div>`;$('practiceCurrent').onclick=()=>{p.v4=p.v4||{};p.v4.section='practice';save();go('lesson',{id:x.id})};$('practiceUse').onclick=()=>{p.v4=p.v4||{};p.v4.section='use';save();go('lesson',{id:x.id})};$('practiceWords').onclick=()=>go('vocab');$('practiceDictionary').onclick=openDictionary;$('practiceExam').onclick=()=>go('exam',{level:state.level});$('practicePlacement').onclick=()=>window.open('placement-test/index.html','_blank')}
function helpText(t){if(!state.wordHelp)return esc(t);let s=esc(t);Object.keys(DICT).filter(k=>!k.includes(' ')).sort((a,b)=>b.length-a.length).slice(0,500).forEach(k=>{const r=new RegExp(`\\b(${k.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')})\\b`,'gi');s=s.replace(r,'<span class="helpWord" data-word="$1">$1</span>')});return s}
function paras(t){return String(t||'').split(/\n\s*\n/).filter(Boolean).map(x=>`<p>${helpText(x)}</p>`).join('')}function bulletList(a,cls='activityList'){return`<ul class="${cls}">${(a||[]).map(x=>`<li>${helpText(x)}</li>`).join('')}</ul>`}function grammarConceptType(title=''){const t=String(title).toLowerCase();if(/past|present|future|perfect|continuous/.test(t))return'Time';if(/conditional|wish|if only/.test(t))return'Condition → result';if(/modal|can|could|may|must|should/.test(t))return'Speaker attitude';if(/passive|causative/.test(t))return'Focus on action/result';if(/relative|participle/.test(t))return'Add information';if(/reported|stance|hedg/.test(t))return'Report & distance';if(/quantifier|countable|uncountable/.test(t))return'Quantity';if(/cohesion|connector|discourse|concession|contrast/.test(t))return'Connect ideas';return'Form → meaning'}
function conceptVisual(x){const e=x.grammar?.examples?.[0]||'',v=(x.vocab||[]).slice(0,4).map(a=>a.word),use=String(x.realWorldTask||x.speaking||x.writing||'Use the language in your own real-life situation.').replace(/\s+/g,' ').trim();return`<div class="conceptVisual conceptJourney" role="group" aria-label="Learning journey for ${esc(x.grammar?.title||'today’s English')}"><article class="conceptStep situationStep"><span class="conceptStepNo">1</span><small>Situation</small><strong>${esc(x.topicTitle||x.unitTitle)}</strong><p>Where and why this English is used.</p></article><div class="conceptArrow" aria-hidden="true">→</div><article class="conceptStep meaningStep"><span class="conceptStepNo">2</span><small>How the English works</small><strong>${esc(x.grammar?.title||'Target language')}</strong><p>${esc(grammarConceptType(x.grammar?.title))}</p></article><div class="conceptArrow" aria-hidden="true">→</div><article class="conceptStep exampleStep"><span class="conceptStepNo">3</span><small>What you can say</small><strong>${esc(e||'Use the model language from this lesson.')}</strong><p>Notice the meaning, form and natural word order.</p></article><div class="conceptArrow" aria-hidden="true">→</div><article class="conceptStep useStep"><span class="conceptStepNo">4</span><small>Use it</small><strong>${esc(use.length>118?use.slice(0,115)+'…':use)}</strong><p>Make the language personal and communicative.</p></article>${v.length?`<div class="conceptWords"><b>Useful words</b>${v.map(w=>`<span>${esc(w)}</span>`).join('')}</div>`:''}</div>`}
function ill(x,compact=false){return x.illustration?`<div class="lessonVisualSet"><figure class="lessonIllustration ${compact?'compact':''}"><img src="${esc(x.illustration)}" alt="Original illustration for ${esc(x.topicTitle||x.unitTitle||'the lesson')}"><figcaption>${esc(x.topicTitle||'Real-world lesson')}</figcaption></figure>${compact?'':conceptVisual(x)}</div>`:''}
function pedagogyBox(x){const ep=x._ep||{};return`<section class="explainPanel"><div class="eyebrow">Understand the language</div><h3>What is happening — and why?</h3><div class="explainGrid"><div><b>What the form does</b><p>${helpText(ep.grammarWhy||x.grammar?.rule||'')}</p></div><div><b>How the form is built</b><p>${helpText(ep.grammarForm||x.grammar?.rule||'')}</p></div></div><details><summary>Common mistakes and how to avoid them</summary>${bulletList(ep.commonMistakes||[])}</details></section>`}
function methodPanel(title,items,why){return`<section class="methodPanel"><div><div class="eyebrow">Method</div><h3>${esc(title)}</h3>${why?`<p>${esc(why)}</p>`:''}</div>${bulletList(items||[],'methodSteps')}</section>`}
function extraActivitiesHtml(x){const a=x._ep?.activities||[];return`<section class="activityLab"><div class="eyebrow">More practice</div><h3>Activity lab</h3><div class="activityCards">${a.map((o,i)=>`<article><span>${i+1}</span><div><b>${esc(o.title)}</b><p>${helpText(o.task)}</p></div></article>`).join('')}</div></section>`}
function dialogue(a){return`<div class="dialogue">${(a||[]).map((x,i)=>`<p><b>${i%2?'B':'A'}:</b> ${helpText(String(x).replace(/^[AB]:\s*/,''))}</p>`).join('')}</div>`}
function v4State(p){p.v4=p.v4||{section:'learn',builders:{},objective:{},plan:{}};p.v4.builders=p.v4.builders||{};p.v4.objective=p.v4.objective||{};p.v4.plan=p.v4.plan||{};return p.v4}
function v4Goal(x){const v=x._v4||{};return`<div class="lessonGoal"><div class="goalIcon">◎</div><div><div class="eyebrow">Lesson goal</div><p>${helpText(v.goal||x.realWorldTask||x.subtitle||'Use today’s English confidently.')}</p></div><span class="interactionBadge">${v.interactionTarget||12}+ interactions</span></div>`}
function v4Scenes(x){const a=x._v4?.scenes||[];return a.length?`<div class="visualStory">${a.map(o=>`<article class="sceneCard"><div class="sceneIcon">${esc(o.icon||'•')}</div><div><b>${esc(o.title)}</b><p>${helpText(o.text)}</p></div></article>`).join('')}</div>`:''}
function v4KeyLanguage(x){const custom=x._v4?.keyLanguage;if(custom?.length)return`<section class="softSection keyLanguageSection"><div class="eyebrow">Key language</div><ul class="phraseChips">${custom.map(a=>`<li>${helpText(a)}</li>`).join('')}</ul></section>`;return`<section class="softSection keyLanguageSection"><div class="eyebrow">Key language</div><ul class="phraseChips">${(x.grammar?.examples||[]).map(a=>`<li>${helpText(a)}</li>`).join('')}${(x.usefulPhrases||[]).slice(0,3).map(a=>`<li>${helpText(a)}</li>`).join('')}</ul></section>`}
function v4Dialogue(x){const a=x._v4?.realLifeDialogue||x.miniDialogue||[];return a.length?`<section class="dialogueCard"><div class="eyebrow">See it in context</div><h3>Real-life exchange</h3><div class="dialogue">${a.map((line,i)=>{const text=String(line);const m=text.match(/^([^:]+):\s*(.*)$/);return`<p><b>${esc(m?m[1]:(i%2?'B':'A'))}:</b> ${helpText(m?m[2]:text.replace(/^[AB]:\s*/,''))}</p>`}).join('')}</div></section>`:''}
function v4CanDo(x){const a=x._v4?.canDo||[];return`<section class="canDoCard"><div class="eyebrow">Review</div><h3>I can now…</h3><div class="canDoList">${a.map(t=>`<label><input type="checkbox"> <span>${helpText(t)}</span></label>`).join('')}</div></section>`}
function v4ObjectiveItems(x){const out=(x.quiz||[]).slice(0,4).map(q=>({prompt:q.prompt,options:q.options,answer:q.answer,explanation:q.explanation}));const vs=(x.vocab||[]).slice(0,4);const defs=vs.map(v=>v.definition);vs.forEach((v,i)=>out.push({prompt:`Which definition matches “${v.word}”?`,options:defs,answer:i,explanation:`${v.word}: ${v.definition}`}));return out}
function v4ObjectiveBlock(x,p,key='v4'){const st=v4State(p),items=v4ObjectiveItems(x);return`<section class="practiceDeck"><div class="sectionTitleRow"><div><div class="eyebrow">Controlled practice</div><h3>Quick practice deck</h3></div><span>${items.length} questions</span></div>${items.map((q,i)=>`<div class="practiceQuestion"><b>${i+1}. ${esc(q.prompt)}</b><div class="options">${q.options.map((o,j)=>`<label class="option"><input type="radio" name="${key}-${i}" value="${j}" ${Number(st.objective[key+i])===j?'checked':''}><span><b>${String.fromCharCode(65+j)}.</b> ${esc(o)}</span></label>`).join('')}</div><div id="v4fb-${key}-${i}"></div></div>`).join('')}<button class="secondary v4CheckObjective" data-v4-key="${esc(key)}">Check ${items.length} answers</button></section>`}
function v4BuilderBlock(x,p){const st=v4State(p),a=(x.grammar?.examples||[]).slice(0,2);if(!a.length)return'';return`<section class="builderDeck"><div class="eyebrow">Build the sentence</div><h3>Put the language back together</h3>${a.map((e,i)=>{const words=String(e).replace(/[.!?]+$/,'').split(/\s+/);const shuffled=[...words].reverse().join(' · ');return`<div class="builderItem" data-builder-answer="${esc(e)}"><div class="wordTiles">${esc(shuffled)}</div><label>Write the sentence in the natural order<input class="builderInput" data-builder-key="${i}" value="${esc(st.builders[i]||'')}" autocomplete="off"></label><button type="button" class="ghost builderCheck">Check sentence</button><div class="builderFeedback"></div></div>`}).join('')}</section>`}
function v4PlanBlock(x,p){const st=v4State(p),qs=x._v4?.writingModel?.plan||['Who will read this?','What are your main ideas?','What should the reader understand or do?'];return`<section class="planningBoard"><div class="eyebrow">Before you draft</div><h3>Three-minute plan</h3>${qs.map((q,i)=>`<label><b>${esc(q)}</b><textarea class="v4PlanInput" data-plan-key="${i}" rows="2" placeholder="Short notes are enough…">${esc(st.plan[i]||'')}</textarea></label>`).join('')}</section>`}
function lessonTabsHtml(p,sections){const st=v4State(p);if(!sections.some(s=>s.key===st.section))st.section='learn';return`<nav class="lessonSectionTabs" aria-label="Lesson sections">${sections.map((s,i)=>`<button type="button" data-lesson-tab="${s.key}" class="${st.section===s.key?'active':''}"><span class="tabNumber">${i+1}</span><span class="tabLabel">${esc(s.label)}</span></button>`).join('')}</nav>`}
function lessonSectionsHtml(p,sections){const st=v4State(p);return sections.map((s,i)=>`<section class="lessonSection ${st.section===s.key?'active':''}" data-lesson-section="${s.key}">${s.html}<div class="sectionStepper">${i?`<button type="button" class="ghost lessonSectionMove" data-section-target="${sections[i-1].key}">← ${esc(sections[i-1].label)}</button>`:'<span></span>'}${i<sections.length-1?`<button type="button" class="primary lessonSectionMove" data-section-target="${sections[i+1].key}">${esc(sections[i+1].label)} →</button>`:'<span></span>'}</div></section>`).join('')}
function bindLessonTabs(x,p){const st=v4State(p),show=key=>{st.section=key;document.querySelectorAll('[data-lesson-tab]').forEach(b=>b.classList.toggle('active',b.dataset.lessonTab===key));document.querySelectorAll('[data-lesson-section]').forEach(sec=>sec.classList.toggle('active',sec.dataset.lessonSection===key));save();document.querySelector('.lessonHead')?.scrollIntoView({behavior:'smooth',block:'start'})};document.querySelectorAll('[data-lesson-tab]').forEach(b=>b.onclick=()=>show(b.dataset.lessonTab));document.querySelectorAll('.lessonSectionMove').forEach(b=>b.onclick=()=>show(b.dataset.sectionTarget))}
function bindV4Practice(x,p){const st=v4State(p),items=v4ObjectiveItems(x);document.querySelectorAll('.v4CheckObjective').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.v4Key;let correct=0,answered=0;items.forEach((q,i)=>{const r=document.querySelector(`input[name="${key}-${i}"]:checked`),v=r?Number(r.value):null;if(v!==null){answered++;st.objective[key+i]=v}if(v===q.answer)correct++;const fb=$(`v4fb-${key}-${i}`);if(fb)fb.innerHTML=v===q.answer?`<div class="feedback good">Correct. ${esc(q.explanation||'')}</div>`:`<div class="feedback bad">Review this item. ${esc(q.explanation||'')}</div>`});save();soundFx(answered&&correct===answered?'good':correct?'tap':'bad');say(`${correct}/${items.length} correct`) });document.querySelectorAll('.builderInput').forEach(inp=>inp.oninput=()=>{st.builders[inp.dataset.builderKey]=inp.value;save()});document.querySelectorAll('.builderCheck').forEach(btn=>btn.onclick=()=>{const item=btn.closest('.builderItem'),input=item.querySelector('.builderInput'),fb=item.querySelector('.builderFeedback'),norm=a=>String(a||'').toLowerCase().replace(/[^a-z0-9' ]/g,'').replace(/\s+/g,' ').trim(),ok=norm(input.value)===norm(item.dataset.builderAnswer);fb.innerHTML=ok?'<div class="feedback good">Correct sentence order.</div>':`<div class="feedback bad">Try again. Compare the word order with the lesson model.</div>`;soundFx(ok?'good':'bad')});document.querySelectorAll('.v4PlanInput').forEach(inp=>inp.oninput=()=>{st.plan[inp.dataset.planKey]=inp.value;save()})}
function sectionSet(x,p){const hero=ill(x),ep=x._ep||{},v=x._v4||{},why=v.whyItMatters||'',moreRead=[...(x.readingQuestions||[]),...(v.extraQuestions||[])],moreListen=[...listeningPrompts(),...(v.extraQuestions||[])];
 if(x.day===1)return[
  {key:'learn',label:'Learn',html:`${v4Goal(x)}${hero}${v4Scenes(x)}${v4Dialogue(x)}${v4KeyLanguage(x)}<div class="grid2 lessonSplit"><section><h3>Vocabulary in context</h3><div class="vocabGrid">${x.vocab.map(v=>`<div class="vocab"><div><strong class="helpWord" data-word="${esc(v.word)}">${esc(v.word)}</strong> <span class="posTag">${esc(v.pos||'word')}</span></div><p>${esc(v.definition)}</p>${v.example?`<small>${esc(v.example)}</small>`:''}</div>`).join('')}</div></section><section><h3>Expressions and phrasal verbs</h3><div class="vocabGrid oneCol">${x.phrasal.map(v=>`<div class="vocab"><strong class="helpWord" data-word="${esc(v.word)}">${esc(v.word)}</strong><p>${esc(v.definition)}</p></div>`).join('')}</div></section></div>`},
  {key:'understand',label:'Understand',html:`<div class="eyebrow">Grammar and use of English</div><h2>${esc(x.grammar.title)}</h2><div class="whyCard"><b>Why this matters</b><p>${helpText(why)}</p></div><div class="languageBox"><p>${helpText(x.grammar.rule)}</p>${x.grammar.examples.map(e=>`<p><b>Model:</b> ${helpText(e)}</p>`).join('')}</div>${pedagogyBox({...x,_ep:{...ep,grammarWhy:v.grammarWhy||ep.grammarWhy,grammarForm:v.grammarForm||ep.grammarForm,commonMistakes:v.commonMistakes||ep.commonMistakes}})}<section class="pronunciationMini"><div class="eyebrow">Pronunciation</div><h3>Say the meaning, not separate words</h3><p>${helpText(v.pronunciationWhy||ep.pronunciationWhy||`Focus on ${x.pronunciationFocus}.`)}</p></section>`},
  {key:'practice',label:'Practice',html:`${v4BuilderBlock(x,p)}${v4ObjectiveBlock(x,p,'core')}${extraActivitiesHtml(x)}`},
  {key:'use',label:'Use',html:`<div class="eyebrow">Use it yourself</div><h2>From rule to communication</h2><p class="aiIntro">Explain the meaning in your own words, then use the language in a short response. AI checks meaning separately from language accuracy.</p>${aiPracticeBlock(x,p,'grammar',[`Why would a speaker use ${x.grammar.title} in this situation? Explain the meaning, not only the form.`,`Create one new example of ${x.grammar.title} for ${x.topicTitle||x.unitTitle}, then explain why it fits.`],`${x.grammar.rule}\n${x.grammar.examples.join(' / ')}\n${v.grammarWhy||ep.grammarWhy||''}`)}${recordBox(x.id+'-v4-use',x.realWorldTask||x.speaking,'Speaking',x.realWorldTask||x.speaking,x.pronunciationFocus)}`},
  {key:'review',label:'Review',html:`${v4CanDo(x)}<div class="factCard"><b>Real-world connection</b><p>${helpText(x.fact)}</p></div><div class="reviewPrompt"><b>One-minute retrieval</b><p>Close the explanations. Say the grammar idea, one example, one common mistake and one useful phrase from memory.</p></div>`}
 ];
 if(x.day===2)return[
  {key:'learn',label:'Before reading',html:`${v4Goal(x)}${hero}${v4Scenes(x)}${methodPanel('How to read this text',ep.readingMethod,'Use a first read for meaning and a second read for evidence.')}`},
  {key:'understand',label:'Read',html:`<div class="eyebrow">Main text</div><h2>${esc(x.readingTitle)}</h2><div class="readingBox premiumReading">${paras(x.reading)}</div><div class="grid2 lessonSplit"><div class="factCard"><b>Did you know?</b><p>${helpText(x.fact)}</p></div><div class="challengeCard"><b>Think and apply</b><p>${helpText(x.realWorldTask)}</p></div></div>`},
  {key:'practice',label:'Questions',html:`<h2>Read actively</h2><p class="aiIntro">Answer from evidence, then paraphrase. A correct idea does not need to copy the exact sentence.</p>${aiPracticeBlock(x,p,'reading',moreRead,x.reading)}`},
  {key:'use',label:'Extend',html:`<div class="eyebrow">Second text</div><h2>Read the situation again from a wider angle</h2><div class="readingBox premiumReading">${paras(ep.extensionPassage||'')}</div><h3>Extension questions</h3>${aiPracticeBlock(x,p,'readingExtra',ep.extensionQuestions||[],ep.extensionPassage||'')}${extraActivitiesHtml(x)}`},
  {key:'review',label:'Review',html:`${v4ObjectiveBlock(x,p,'readingReview')}${v4CanDo(x)}`}
 ];
 if(x.day===3)return[
  {key:'learn',label:'Prepare',html:`${v4Goal(x)}${hero}${v4Scenes(x)}<div class="whyCard"><b>Why this method works</b><p>${helpText(why)}</p></div>`},
  {key:'understand',label:'Listen',html:`<div class="eyebrow">Listening</div><h2>${esc(x.topicTitle||'Listen for meaning')}</h2><div class="languageBox"><p>First listen: main idea. Second listen: details. Open the transcript only after you have tried the questions.</p><div class="buttons"><button class="primary" id="listen">▶ Play listening</button><button class="ghost" id="stopVoice">■ Stop</button></div><details><summary>Transcript — open after listening</summary>${paras(x.listening)}</details></div>`},
  {key:'practice',label:'Questions',html:`<h2>Listening comprehension</h2><p class="aiIntro">Write short answers in your own words. AI checks comprehension separately from grammar.</p>${aiPracticeBlock(x,p,'listening',moreListen,x.listening)}${v4ObjectiveBlock(x,p,'listeningReview')}`},
  {key:'use',label:'Pronounce',html:`${methodPanel('Pronunciation method',ep.pronunciationMethod,`${v.pronunciationWhy||ep.pronunciationWhy||'Pronunciation carries meaning through stress, rhythm, grouping and clear sounds.'} Focus today: ${x.pronunciationFocus}.`)}${recordBox(x.id+'-pronunciation','Read a grammar example or one short section of the transcript. Focus on '+x.pronunciationFocus+'.','Pronunciation',x.grammar.examples?.[0]||x.listening,x.pronunciationFocus)}${extraActivitiesHtml(x)}`},
  {key:'review',label:'Review',html:`${v4CanDo(x)}<div class="reviewPrompt"><b>Listening reflection</b><p>Which part was hardest: identifying the main idea, catching a detail, or hearing the word boundaries? Name one strategy for the next listen.</p></div>`}
 ];
 if(x.day===4)return[
  {key:'learn',label:'Learn',html:`${v4Goal(x)}${hero}${v4Scenes(x)}<div class="grid2 lessonSplit"><section><h3>Useful language</h3>${bulletList(x.usefulPhrases)}</section><section><h3>Mini-dialogue</h3>${dialogue(x.miniDialogue)}</section></div>`},
  {key:'understand',label:'Plan',html:`<div class="whyCard"><b>Why speaking needs a plan</b><p>${helpText(why)}</p></div>${methodPanel('Speaking method',v.speakingMethod||x.speakingSteps,'Plan the message first; then choose language and delivery.')}`},
  {key:'practice',label:'Practice',html:`${v4BuilderBlock(x,p)}${v4ObjectiveBlock(x,p,'speakingPrep')}${extraActivitiesHtml(x)}`},
  {key:'use',label:'Speak',html:`<div class="eyebrow">Main speaking challenge</div><h2>${esc(x.topicTitle||'Real-world speaking')}</h2><div class="challengeCard large"><p>${helpText(x.speaking)}</p></div>${recordBox(x.id+'-speaking','Plan briefly, speak naturally, listen once and improve one specific feature.','Speaking',x.speaking,x.pronunciationFocus)}<div class="challengeCard"><b>Response challenge</b><p>Imagine the listener asks one follow-up question. Add a clear answer with one extra detail.</p></div>${recordBox(x.id+'-speaking-followup','Add a short follow-up response with one extra detail.','Speaking',x.speaking+' Add one follow-up detail.',x.pronunciationFocus)}`},
  {key:'review',label:'Review',html:`${v4CanDo(x)}<div class="reviewPrompt"><b>Self-check</b><p>Was your message easy to follow? Did you use thought groups? Did you improve one feature between attempts?</p></div>`}
 ];
 return[
  {key:'learn',label:'Plan',html:`${v4Goal(x)}${hero}${v4Scenes(x)}${methodPanel('Writing method',ep.writingMethod,'Plan the reader and purpose before correcting grammar.')}<div class="whyCard"><b>Why this matters</b><p>${helpText(why)}</p></div>`},
  {key:'understand',label:'Organise',html:`<div class="eyebrow">Writing structure</div><h2>Build the message before polishing the sentences</h2><p>${helpText(v.writingModel?.model||'Use a clear opening, connected detail and purposeful ending.')}</p><div class="grid2 lessonSplit"><div><h3>Quality checklist</h3>${bulletList(x.writingChecklist)}</div><div class="factCard"><b>Target language</b><p>${helpText(x.grammar.rule)}</p></div></div>`},
  {key:'practice',label:'Prepare',html:`${v4PlanBlock(x,p)}${v4ObjectiveBlock(x,p,'writingPrep')}`},
  {key:'use',label:'Write',html:`<div class="challengeCard"><b>Writing brief</b><p>${helpText(x.writing)}</p></div><div class="writingBox"><textarea id="writing" placeholder="Write your response here…">${esc(p.writing||'')}</textarea><small id="wc">${words(p.writing||'')} words</small><div class="buttons"><button class="secondary" id="aiWritingCheck" ${C.aiEndpoint?'':'disabled'}>Check writing with AI</button></div><div id="aiWritingFeedback" class="aiFeedback">${p.aiWriting?aiFeedbackHtml(p.aiWriting):''}</div></div><div class="factCard"><b>Mini-project</b><p>${helpText(x.homework)}</p></div><div class="writingBox"><textarea id="homework" placeholder="Record notes, observations or project evidence here…">${esc(p.homework||'')}</textarea></div>`},
  {key:'review',label:'Review',html:`${v4CanDo(x)}${quizBlock(x,p,'final')}<div class="reviewPrompt"><b>Final edit</b><p>Read the text as the reader. Remove repetition, clarify one vague sentence, and check that the ending matches the purpose.</p></div>`}
 ]}
function lessonView(id){announceView('lesson');const x=findLesson(id),p=lp(id);state.current=id;state.level=x.levelId;save();const sections=sectionSet(x,p),v=x._v4||{};screen.innerHTML=`<div class="shell"><div class="lessonLayout premiumLessonLayout"><aside class="sidebar premiumLessonSidebar"><div class="eyebrow">${level(x.levelId).cefr} • ${esc(x.unitTitle)}</div><h3 style="margin-top:8px">Lesson ${x.day} of 5</h3><div class="progress" style="margin-top:14px"><div style="width:${x.day*20}%"></div></div><div class="sideList"><button class="sideItem" id="courseBack">← Course map</button><button class="sideItem" id="practiceHub">Practice hub</button><button class="sideItem" id="wordToggle">Word Help: ${state.wordHelp?'On':'Off'}</button><button class="sideItem" id="dictOpen">Dictionary</button></div><div class="sidebarTip"><b>Today’s context</b><p>${esc(x.topicTitle||x.unitTitle)}</p></div></aside><article class="lesson premiumLesson"><header class="lessonHead"><div class="lessonHeadMeta"><div class="eyebrow">${esc(x.type)}</div><span>${x.minutes} min</span></div><h1>${esc(v.displayTitle||x.title)}</h1><p class="lessonSubtitle">${esc(x.subtitle)}</p><p class="lessonSaveStatus">Progress saves automatically${state.sync?.enabled?' • cloud sync on':''}</p></header>${lessonTabsHtml(p,sections)}<div class="lessonBody premiumLessonBody">${lessonSectionsHtml(p,sections)}</div><footer class="lessonFoot"><button class="ghost" id="prevLesson">Previous lesson</button><div class="buttons" style="margin:0"><button class="secondary" id="saveLesson">Save</button><button class="primary" id="completeLesson">${p.done?'Completed':'Complete lesson'}</button></div></footer></article></div></div>`;bindHelp();bindLessonTabs(x,p);bindV4Practice(x,p);$('courseBack').onclick=()=>go('course');$('practiceHub').onclick=()=>go('practice');$('dictOpen').onclick=openDictionary;$('wordToggle').onclick=()=>{state.wordHelp=!state.wordHelp;save();lessonView(id)};const list=lessons(),i=list.findIndex(a=>a.id===id);$('prevLesson').disabled=i<=0;$('prevLesson').onclick=()=>go('lesson',{id:list[i-1].id});$('saveLesson').onclick=()=>capture(x,p);$('completeLesson').onclick=()=>{capture(x,p);p.done=true;const n=list[i+1];if(n)state.current=n.id;log('lesson-complete',{id});soundFx('good');say('Lesson completed.');setTimeout(dashboard,350)};if($('listen'))$('listen').onclick=()=>speak(x.listening);if($('stopVoice'))$('stopVoice').onclick=()=>speechSynthesis.cancel();document.querySelectorAll('.recordBox').forEach(b=>bindRecord(b));if(x.day===5){p.aiWriting=p.aiWriting||null;$('writing').oninput=()=>{p.writing=$('writing').value;$('wc').textContent=words($('writing').value)+' words';save()};$('homework').oninput=()=>{p.homework=$('homework').value;save()};$('aiWritingCheck').onclick=async()=>{const answer=$('writing').value.trim();if(!answer)return say('Write your response first.');const b=$('aiWritingCheck'),fb=$('aiWritingFeedback'),old=b.textContent;b.disabled=true;b.textContent='Checking…';fb.innerHTML='<div class="aiWaiting">Reviewing task achievement and English…</div>';try{const data=await aiJsonp({level:level(x.levelId).cefr,skill:'Writing',question:x.writing,expectedAnswer:'',evidence:`Target grammar: ${x.grammar.title}. ${x.grammar.rule} Checklist: ${(x.writingChecklist||[]).join('; ')}`,studentAnswer:answer});if(!data?.ok)throw Error(data?.error||'AI grading failed.');p.aiWriting=data.grading;save();fb.innerHTML=aiFeedbackHtml(data.grading);soundFx(data.grading?.result==='incorrect'?'bad':'good')}catch(err){fb.innerHTML=`<div class="aiResult bad"><strong>Could not check the writing.</strong><p>${esc(err.message||err)}</p></div>`}finally{b.disabled=false;b.textContent=old}}}bindQuiz(x,p);bindAIPractice(x,p)}
function listeningPrompts(){return['Who are the speakers, or what roles do they have?','What is the main situation or purpose of the conversation?','What action or next step is suggested?','What does one speaker ask to be repeated or clarified?']}
function aiPracticeBlock(x,p,skill,questions,evidence){p.ai=p.ai||{};if(!C.aiEndpoint)return`<div class="notice warn">AI checking is not configured yet.</div>`;return`<div class="aiPractice" data-ai-skill="${esc(skill)}" data-ai-evidence="${esc(evidence||'')}">${(questions||[]).map((q,i)=>{const k=skill+i,a=p.ai[k]?.answer||'',g=p.ai[k]?.grading;return`<div class="aiQuestion" data-ai-index="${i}" data-ai-question="${esc(q)}"><label for="ai-${skill}-${i}"><b>${i+1}. ${esc(q)}</b></label><textarea id="ai-${skill}-${i}" class="aiAnswer" rows="3" placeholder="Type your answer in your own words…">${esc(a)}</textarea><div class="buttons aiButtons"><button type="button" class="secondary aiCheck" data-ai-key="${esc(k)}">Check with AI</button><button type="button" class="ghost aiClear" data-ai-key="${esc(k)}">Clear</button></div><div class="aiFeedback" aria-live="polite">${g?aiFeedbackHtml(g):''}</div></div>`}).join('')}</div>`}
function aiFeedbackHtml(g){const r=g.result==='correct'?'Correct':g.result==='partly_correct'?'Partly correct':'Needs another try',cls=g.result==='correct'?'good':g.result==='partly_correct'?'partial':'bad',score=Number.isFinite(Number(g.score))&&Number.isFinite(Number(g.maxScore))?`<span class="aiScore">${esc(g.score)}/${esc(g.maxScore)}</span>`:'';return`<div class="aiResult ${cls}"><div class="aiResultHead"><strong>${r}</strong>${score}</div><div class="aiChecks"><span>${g.comprehensionCorrect?'✓':'○'} Understanding</span><span>${g.languageCorrect?'✓':'○'} English accuracy</span></div>${g.feedback?`<p><b>Feedback:</b> ${esc(g.feedback)}</p>`:''}${g.languageFeedback?`<p><b>English:</b> ${esc(g.languageFeedback)}</p>`:''}${g.improvedAnswer?`<p><b>Better answer:</b> ${esc(g.improvedAnswer)}</p>`:''}${g.hint&&g.canRetry?`<p class="aiHint"><b>Hint:</b> ${esc(g.hint)}</p>`:''}</div>`}
function aiJsonp(params){return new Promise((resolve,reject)=>{const endpoint=String(C.aiEndpoint||'').trim();if(!endpoint)return reject(new Error('AI endpoint is not configured.'));if(!navigator.onLine)return reject(new Error('Connect to the internet to use AI checking.'));const cb='epAI_'+Date.now()+'_'+Math.random().toString(36).slice(2),script=document.createElement('script');let finished=false;const cleanup=()=>{if(finished)return;finished=true;clearTimeout(timer);try{delete window[cb]}catch(e){window[cb]=undefined}script.remove()};window[cb]=data=>{cleanup();resolve(data)};script.onerror=()=>{cleanup();reject(new Error('The AI service could not be reached.'))};const q=new URLSearchParams({...params,action:'grade',prefix:cb});script.src=endpoint+(endpoint.includes('?')?'&':'?')+q.toString();script.async=true;document.body.appendChild(script);const timer=setTimeout(()=>{cleanup();reject(new Error('The AI check took too long. Try again.'))},30000)})}
function bindAIPractice(x,p){document.querySelectorAll('.aiPractice').forEach(block=>{const skill=block.dataset.aiSkill,evidence=block.dataset.aiEvidence||'';block.querySelectorAll('.aiQuestion').forEach(card=>{const question=card.dataset.aiQuestion||'',area=card.querySelector('.aiAnswer'),check=card.querySelector('.aiCheck'),clear=card.querySelector('.aiClear'),feedback=card.querySelector('.aiFeedback'),key=check.dataset.aiKey;p.ai=p.ai||{};area.oninput=()=>{p.ai[key]=p.ai[key]||{};p.ai[key].answer=area.value;save()};clear.onclick=()=>{area.value='';p.ai[key]={answer:''};feedback.innerHTML='';save()};check.onclick=async()=>{const answer=area.value.trim();if(!answer)return say('Write an answer first.');check.disabled=true;const old=check.textContent;check.textContent='Checking…';feedback.innerHTML='<div class="aiWaiting">Checking meaning and English…</div>';try{const data=await aiJsonp({level:level(x.levelId).cefr,skill:skill==='reading'?'Reading':skill==='listening'?'Listening':skill==='grammar'?'Use of English':skill,question,expectedAnswer:'',evidence:String(evidence).slice(0,3500),studentAnswer:answer});if(!data?.ok)throw new Error(data?.error||'AI grading failed.');p.ai[key]={answer,grading:data.grading,checkedAt:new Date().toISOString()};save();feedback.innerHTML=aiFeedbackHtml(data.grading);soundFx(data.grading?.result==='correct'?'good':data.grading?.result==='incorrect'?'bad':'tap')}catch(err){feedback.innerHTML=`<div class="aiResult bad"><strong>Could not check this answer.</strong><p>${esc(err.message||err)}</p></div>`}finally{check.disabled=false;check.textContent=old}}})})}
function quizBlock(x,p,key){return`<h3 style="margin-top:18px">Checkpoint</h3>${x.quiz.map((q,i)=>`<div class="quizItem"><b>${i+1}. ${esc(q.prompt)}</b><div class="options">${q.options.map((o,j)=>`<label class="option"><input type="radio" name="${key}${i}" value="${j}" ${p.quiz[key+i]===j?'checked':''}><span><b>${String.fromCharCode(65+j)}.</b> ${esc(o)}</span></label>`).join('')}</div><div id="fb${key}${i}"></div></div>`).join('')}<button class="secondary checkQuiz" data-key="${key}">Check answers</button>`}
function bindQuiz(x,p){document.querySelectorAll('.quizItem input[type="radio"]').forEach(r=>r.addEventListener('change',()=>soundFx('tap')));document.querySelectorAll('.checkQuiz').forEach(b=>b.onclick=()=>{const key=b.dataset.key;let correct=0,answered=0;x.quiz.forEach((q,i)=>{const r=document.querySelector(`input[name="${key}${i}"]:checked`),v=r?Number(r.value):null;p.quiz[key+i]=v;if(v!==null)answered++;if(v===q.answer)correct++;document.getElementById('fb'+key+i).innerHTML=v===q.answer?`<div class="feedback good">Correct. ${esc(q.explanation)}</div>`:`<div class="feedback bad">Review this item. ${esc(q.explanation)}</div>`});save();soundFx(answered&&correct===answered?'good':correct?'tap':'bad')})}
function capture(x,p){if($('writing'))p.writing=$('writing').value;if($('homework'))p.homework=$('homework').value;save();say('Progress saved.')}
function speak(t){if(!speechSynthesis)return say('Speech synthesis is unavailable.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='en-GB';u.rate=.9;speechSynthesis.speak(u)}
function recordBox(k,t,skill='Speaking',task='',focus='',allowAI=true){return`<div class="recordBox" data-key="${esc(k)}" data-skill="${esc(skill)}" data-task="${esc(task||t)}" data-focus="${esc(focus)}"><div class="recordPulse">Recording now</div><p>${esc(t)}</p><div class="buttons"><button class="primary startRec">● Record</button><button class="ghost stopRec" disabled>■ Stop</button><button class="ghost playRec" disabled>▶ Play</button>${allowAI?'<button class="secondary aiVoiceCheck" disabled>Check voice with AI</button>':'<span class="formalAiLock">AI feedback unlocks after submission.</span>'}<button class="danger delRec" disabled>Delete</button></div><audio controls hidden></audio><small class="status">No recording loaded.</small><div class="voiceAiFeedback" aria-live="polite"></div></div>`}
function db(){return new Promise((ok,no)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}async function put(k,b){const d=await db();return new Promise((ok,no)=>{const t=d.transaction(STORE,'readwrite');t.objectStore(STORE).put(b,k);t.oncomplete=ok;t.onerror=()=>no(t.error)})}async function get(k){try{const d=await db();return await new Promise((ok,no)=>{const t=d.transaction(STORE);const r=t.objectStore(STORE).get(k);r.onsuccess=()=>ok(r.result||null);r.onerror=()=>no(r.error)})}catch(e){return null}}async function del(k){const d=await db();return new Promise(ok=>{const t=d.transaction(STORE,'readwrite');t.objectStore(STORE).delete(k);t.oncomplete=ok})}async function keys(){const d=await db();return new Promise(ok=>{const t=d.transaction(STORE);const r=t.objectStore(STORE).getAllKeys();r.onsuccess=()=>ok(r.result||[])})}
async function bindRecord(box){if(!box||box.dataset.epBound==='1')return;box.dataset.epBound='1';const k=box.dataset.key,a=box.querySelector('audio'),st=box.querySelector('.startRec'),sp=box.querySelector('.stopRec'),pl=box.querySelector('.playRec'),de=box.querySelector('.delRec'),ai=box.querySelector('.aiVoiceCheck'),feedback=box.querySelector('.voiceAiFeedback'),status=box.querySelector('.status');let old=await get(k);const enable=blob=>{if(blob){a.src=URL.createObjectURL(blob);a.hidden=false;pl.disabled=false;de.disabled=false;if(ai)ai.disabled=!C.aiEndpoint;status.textContent='Saved recording loaded.'}};if(old)enable(old);let rec,stream,chunks=[];st.onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Recording is not supported in this browser.');stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});chunks=[];const types=['audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus'];const mt=types.find(t=>MediaRecorder.isTypeSupported?.(t));rec=mt?new MediaRecorder(stream,{mimeType:mt,audioBitsPerSecond:48000}):new MediaRecorder(stream,{audioBitsPerSecond:48000});rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);rec.onstop=async()=>{const type=rec.mimeType||chunks[0]?.type||'audio/webm',b=new Blob(chunks,{type});await put(k,b);enable(b);status.textContent='Recording saved on this device.';box.classList.remove('recording');stream?.getTracks().forEach(t=>t.stop());stream=null;soundFx('tap')};rec.start(250);box.classList.add('recording');st.disabled=true;sp.disabled=false;if(ai)ai.disabled=true;status.textContent='Recording… tap Stop when finished.'}catch(e){box.classList.remove('recording');stream?.getTracks().forEach(t=>t.stop());stream=null;say(location.protocol==='https:'||location.hostname==='localhost'?'Microphone unavailable. Allow microphone access in browser settings.':'Microphone recording requires an HTTPS hosted app.')}};sp.onclick=()=>{if(rec?.state==='recording'){rec.stop();st.disabled=false;sp.disabled=true}};pl.onclick=()=>a.play();de.onclick=async()=>{await del(k);a.pause();a.hidden=true;a.removeAttribute('src');pl.disabled=true;de.disabled=true;if(ai)ai.disabled=true;feedback.innerHTML='';status.textContent='Recording deleted.'};if(ai)ai.onclick=async()=>{const blob=await get(k);if(!blob)return say('Record your answer first.');ai.disabled=true;const oldText=ai.textContent;ai.textContent='Checking…';feedback.innerHTML='<div class="aiWaiting">Listening to your recording…</div>';try{const g=await gradeVoiceBlob(blob,{level:level(state.level).cefr,skill:box.dataset.skill||'Speaking',task:box.dataset.task||'',focus:box.dataset.focus||''});feedback.innerHTML=voiceFeedbackHtml(g);soundFx(g?.result==='correct'?'good':g?.result==='incorrect'?'bad':'tap')}catch(err){feedback.innerHTML=`<div class="aiResult bad"><strong>Voice check failed.</strong><p>${esc(err.message||err)}</p></div>`}finally{ai.disabled=false;ai.textContent=oldText}}}
function bindHelp(){document.querySelectorAll('.helpWord').forEach(e=>e.onclick=ev=>wordPopup(e.dataset.word||e.textContent,ev))}function wordPopup(w,e){const x=DICT[String(w).toLowerCase()];if(!x)return;popup.innerHTML=`<button class="ghost" id="closePop" style="float:right">×</button><h3>${esc(x.word)}</h3><small>${esc(x.pos)}</small><p>${esc(x.definition)}</p><small>${esc(x.example)}</small><div class="buttons"><button class="secondary" id="sayWord">Listen</button><button class="ghost" id="saveWord">${state.vocab.includes(x.word.toLowerCase())?'Saved':'Add to vocabulary'}</button></div>`;popup.style.left=Math.min(innerWidth-345,Math.max(10,e.clientX+10))+'px';popup.style.top=Math.min(innerHeight-250,Math.max(75,e.clientY+10))+'px';popup.hidden=false;$('closePop').onclick=()=>popup.hidden=true;$('sayWord').onclick=()=>speak(x.word);$('saveWord').onclick=()=>{toggleWord(x.word.toLowerCase());$('saveWord').textContent=state.vocab.includes(x.word.toLowerCase())?'Saved':'Add to vocabulary'}}function toggleWord(w){state.vocab.includes(w)?state.vocab=state.vocab.filter(x=>x!==w):state.vocab.push(w);save();say('Vocabulary updated.')}
function openDictionary(){drawer.classList.add('open');drawer.innerHTML=`<div style="display:flex;justify-content:space-between"><div><div class="eyebrow">Learner dictionary</div><h2>Dictionary</h2></div><button class="ghost" id="closeDraw">×</button></div><div class="field" style="margin-top:15px"><label>Search</label><input id="dictSearch" placeholder="Course word or phrasal verb"></div><div id="dictResults"><div class="notice" style="margin-top:12px">This offline dictionary covers core course vocabulary. Sound plays only when you press Listen.</div></div>`;$('closeDraw').onclick=()=>drawer.classList.remove('open');$('dictSearch').oninput=()=>{const q=$('dictSearch').value.toLowerCase().trim(),r=Object.values(DICT).filter(x=>x.word.includes(q)||x.definition.includes(q)).slice(0,20);$('dictResults').innerHTML=r.map(x=>`<div class="dictEntry"><h3>${esc(x.word)}</h3><small>${esc(x.pos)}</small><p>${esc(x.definition)}</p><div class="buttons"><button class="secondary" data-say="${esc(x.word)}">Listen</button><button class="ghost" data-save="${esc(x.word.toLowerCase())}">${state.vocab.includes(x.word.toLowerCase())?'Saved':'Add'}</button></div></div>`).join('')||'<div class="notice" style="margin-top:12px">No local entry found.</div>';document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>speak(b.dataset.say));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{toggleWord(b.dataset.save);b.textContent=state.vocab.includes(b.dataset.save)?'Saved':'Add'})}}
function vocabView(){announceView('progress');const a=state.vocab.map(w=>DICT[w]).filter(Boolean);screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Personal notebook</div><h1>My vocabulary</h1><p class="lead">Review saved words and pronunciation.</p></section><section class="card" style="margin-top:16px">${a.length?a.map(x=>`<div class="dictEntry"><h3>${esc(x.word)}</h3><p>${esc(x.definition)}</p><button class="secondary" data-say="${esc(x.word)}">Listen</button></div>`).join(''):'<div class="notice">No saved words yet.</div>'}</section></div>`;document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>speak(b.dataset.say))}
function buildExam(id){const l=level(id),items=l.units.flatMap((u,i)=>{const q=u.lessons[0].quiz;return[q[i%q.length],q[(i+2)%q.length]]}).slice(0,20);return{level:id,items,answers:{},marked:{},i:0,time:2700,started:false,submitted:false,writing:'',writingTask:l.units.at(-1).lessons.at(-1).writing,speakingTask:l.units.at(-1).lessons.at(-1).speaking}}
function examStart(id){announceView('more');if(!exam||exam.level!==id)exam=buildExam(id);const l=level(id);if(!exam.started){screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">${l.cefr} formal assessment</div><h1>${esc(l.name)} end-of-level exam</h1><p class="lead">20 objective questions, writing and recorded speaking. Dictionary and Word Help are disabled.</p><div class="buttons"><button class="primary" id="startExam">Start 45-minute exam</button><button class="ghost" id="backCourse">Course map</button></div></section></div>`;$('startExam').onclick=()=>{exam.started=true;examQuestion()};$('backCourse').onclick=()=>go('course')}else exam.submitted?examResult():examQuestion()}
function tick(){clearInterval(timer);timer=setInterval(()=>{exam.time--;const e=document.getElementById('timer');if(e)e.textContent=fmt(exam.time);if(exam.time<=0)submitExam()},1000)}function fmt(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function examQuestion(){tick();const q=exam.items[exam.i];screen.innerHTML=`<div class="shell"><section class="card"><div style="display:flex;justify-content:space-between"><div><div class="eyebrow">Formal exam</div><h2>Question ${exam.i+1} of ${exam.items.length}</h2></div><div class="timer" id="timer">${fmt(exam.time)}</div></div><div class="examNav">${exam.items.map((_,i)=>`<button data-q="${i}" class="${exam.answers[i]!==undefined?'answered':''} ${exam.marked[i]?'marked':''}">${i+1}</button>`).join('')}</div><div class="quizItem"><h3>${esc(q.prompt)}</h3><div class="options">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${exam.answers[exam.i]===i?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b> ${esc(o)}</span></label>`).join('')}</div></div><label><input id="mark" type="checkbox" ${exam.marked[exam.i]?'checked':''}> Mark for review / not sure</label><div class="buttons"><button class="ghost" id="prev" ${exam.i===0?'disabled':''}>Previous</button><button class="secondary" id="review">Review</button><button class="primary" id="next">${exam.i===exam.items.length-1?'Review':'Next'}</button></div></section></div>`;document.querySelectorAll('[name=answer]').forEach(r=>r.onchange=()=>{exam.answers[exam.i]=Number(r.value);soundFx('tap')});$('mark').onchange=()=>exam.marked[exam.i]=$('mark').checked;document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{exam.i=Number(b.dataset.q);examQuestion()});$('prev').onclick=()=>{exam.i--;examQuestion()};$('next').onclick=()=>{exam.i<exam.items.length-1?(exam.i++,examQuestion()):examReview()};$('review').onclick=examReview}
function examReview(){clearInterval(timer);screen.innerHTML=`<div class="shell"><section class="card"><div class="eyebrow">Review</div><h1>Objective section</h1><div class="metrics"><div class="metric"><small>Answered</small><strong>${Object.keys(exam.answers).length}</strong></div><div class="metric"><small>Unanswered</small><strong>${exam.items.length-Object.keys(exam.answers).length}</strong></div><div class="metric"><small>Marked</small><strong>${Object.values(exam.marked).filter(Boolean).length}</strong></div><div class="metric"><small>Time</small><strong>${fmt(exam.time)}</strong></div></div><div class="buttons"><button class="ghost" id="returnQ">Return</button><button class="primary" id="production">Writing and speaking</button></div></section></div>`;$('returnQ').onclick=examQuestion;$('production').onclick=examProduction}
function examProduction(){screen.innerHTML=`<div class="shell"><section class="card"><div class="eyebrow">Productive skills</div><h1>Writing and speaking</h1><div class="writingBox"><h3>Writing</h3><p>${esc(exam.writingTask)}</p><textarea id="examWriting">${esc(exam.writing)}</textarea></div>${recordBox('exam-'+exam.level+'-speaking',exam.speakingTask,'Speaking',exam.speakingTask,'task achievement, intelligibility, fluency, grammar and vocabulary',false)}<div class="buttons"><button class="ghost" id="backReview">Objective review</button><button class="primary" id="submit">Submit exam</button></div></section></div>`;bindRecord(document.querySelector('.recordBox'));$('examWriting').oninput=()=>exam.writing=$('examWriting').value;$('backReview').onclick=examReview;$('submit').onclick=submitExam}
function submitExam(){clearInterval(timer);exam.submitted=true;const c=exam.items.filter((q,i)=>exam.answers[i]===q.answer).length,p=Math.round(c/exam.items.length*100);state.exams[exam.level]={at:new Date().toISOString(),correct:c,total:exam.items.length,percent:p,answers:exam.answers,writing:exam.writing,writingTask:exam.writingTask,speakingTask:exam.speakingTask,speakingKey:'exam-'+exam.level+'-speaking',status:'Pending writing and speaking review',aiFinal:null};log('exam-submitted',{level:exam.level,percent:p});examResult()}
function formalWritingFeedbackHtml(g){if(!g)return'';return`<div class="aiResult partial"><div class="aiResultHead"><strong>Writing • ${esc(g.cefrEstimate||'Diagnostic')}</strong>${Number.isFinite(Number(g.score))?`<span class="aiScore">${esc(g.score)}/${esc(g.maxScore||5)}</span>`:''}</div>${g.taskAchievement?`<p><b>Task achievement:</b> ${esc(g.taskAchievement)}</p>`:''}${g.organisation?`<p><b>Organisation:</b> ${esc(g.organisation)}</p>`:''}${g.grammar?`<p><b>Grammar:</b> ${esc(g.grammar)}</p>`:''}${g.vocabulary?`<p><b>Vocabulary:</b> ${esc(g.vocabulary)}</p>`:''}${g.feedback?`<p><b>Diagnostic summary:</b> ${esc(g.feedback)}</p>`:''}</div>`}
async function gradeEndLevelAI(){const r=state.exams[exam.level],l=level(exam.level);if(!r||!exam?.submitted)return say('Submit the exam before AI grading.');if(!gatewayEndpoint())return say('AI Gateway is not configured.');r.aiFinal={status:'grading',startedAt:new Date().toISOString()};save();examResult();try{let writing=null,speaking=null;if(String(r.writing||'').trim()){const requestId='elwrite_'+Date.now()+'_'+Math.random().toString(36).slice(2);await postGateway({action:'gradePlacementWriting',requestId,level:l.cefr,skill:'End-of-level writing',question:r.writingTask||exam.writingTask||'',studentAnswer:r.writing,wordMin:'',wordMax:''});const result=await waitGatewayResult(requestId,45);if(!result?.ok)throw Error(result?.error||'Writing grading failed.');writing=result.grading}const blob=await get(r.speakingKey);if(blob)speaking=await gradeVoiceBlob(blob,{level:l.cefr,skill:'End-of-level speaking',task:r.speakingTask||exam.speakingTask||'',focus:'task achievement, intelligibility, fluency, grammar and vocabulary',formalAssessment:true});r.aiFinal={status:'complete',completedAt:new Date().toISOString(),writing,speaking};r.status='AI productive-skills review complete';save();soundFx('good');examResult()}catch(err){r.aiFinal={status:'error',error:String(err.message||err)};r.status='AI review needs retry';save();say('AI grading failed: '+(err.message||err));examResult()}}
function examResult(){const r=state.exams[exam.level],l=level(exam.level),ai=r.aiFinal;const aiHtml=ai?.status==='complete'?`<section class="ai-final-report"><div class="eyebrow">Final-only AI review</div><h2>Writing and speaking</h2>${ai.writing?formalWritingFeedbackHtml(ai.writing):'<div class="notice">No writing response was available for AI grading.</div>'}${ai.speaking?voiceFeedbackHtml(ai.speaking):'<div class="notice">No speaking recording was available on this device.</div>'}<p class="aiHint"><small>This is a diagnostic course result, not an official CEFR certificate.</small></p></section>`:ai?.status==='grading'?'<div class="notice"><b>AI grading is in progress.</b> Feedback is available only because the exam has already been submitted.</div>':ai?.status==='error'?`<div class="notice warn"><b>AI grading needs retry.</b> ${esc(ai.error||'')}</div>`:'';screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">${l.cefr} exam submitted</div><h1>Objective score: ${r.percent}%</h1><p class="lead">The exam is locked. Writing and speaking feedback can now be generated; no AI assistance was available while the exam was active.</p>${aiHtml}<div class="buttons">${gatewayEndpoint()?`<button class="primary" id="gradeEndAI" ${ai?.status==='grading'?'disabled':''}>${ai?.status==='complete'?'Re-grade writing & speaking with AI':'Grade writing & speaking with AI'}</button>`:''}<button class="secondary" id="downloadExam">Download exam package</button><button class="secondary" id="sendExam">Submit to teacher</button><button class="ghost" id="dash">Dashboard</button></div></section></div>`;$('gradeEndAI')&&($('gradeEndAI').onclick=gradeEndLevelAI);$('downloadExam').onclick=()=>exportPackage('exam',exam.level);$('sendExam').onclick=()=>sendTeacher('exam',exam.level);$('dash').onclick=dashboard}
function progressView(){announceView('progress');const l=level(state.level),p=prog(l.id),examRows=Object.entries(state.exams||{}).map(([id,r])=>`<div class="examResultRow"><div><b>${esc(level(id).cefr)} exam</b><br><small>${esc(r.status||'Submitted')}</small></div><strong>${Number.isFinite(Number(r.percent))?r.percent+'%':'—'}</strong></div>`).join('');screen.innerHTML=`<div class="shell"><section class="hero"><div class="progressHero"><div class="progressRing" style="--progress:${p.p}%"><strong>${p.p}%</strong></div><div><div class="eyebrow">Learning progress</div><h1>${esc(l.cefr)} • ${esc(l.name)}</h1><p class="lead">${p.n} of ${p.total} lessons completed. ${state.vocab.length} vocabulary items saved.</p></div></div></section><section class="card" style="margin-top:14px"><div class="mobileSectionTitle"><h2>Backups and results</h2><small>Keep your work safe</small></div><div class="mobileActionGrid"><button class="mobileActionCard primaryCard" id="progressBackup"><b>Export backup</b><small>Download lessons, writing, exams and recordings.</small></button><label class="mobileActionCard" for="progressRestore"><b>Restore backup</b><small>Move your saved work back onto this device.</small><input id="progressRestore" type="file" accept=".zip,.json" hidden></label><button class="mobileActionCard" id="protectStorage"><b>Protect local data</b><small>Ask the browser to keep app storage when space is low.</small></button><button class="mobileActionCard" id="openWords"><b>Vocabulary notebook</b><small>Review ${state.vocab.length} saved words.</small></button></div></section><section class="card" style="margin-top:14px"><h2>Exam history</h2><div class="examResultList" style="margin-top:13px">${examRows||'<div class="notice">No end-of-level exam has been submitted yet.</div>'}</div></section></div>`;$('progressBackup').onclick=exportBackup;$('progressRestore').onchange=e=>restoreBackup(e.target.files[0]);$('openWords').onclick=()=>go('vocab');$('protectStorage').onclick=async()=>{if(window.EnglishPathwaysMobile?.requestPersistentStorage){const ok=await window.EnglishPathwaysMobile.requestPersistentStorage();say(ok?'Browser storage protection is enabled or granted.':'The browser did not grant persistent storage. Backups remain important.')}else say('Storage protection is unavailable in this browser.')}}

function avatarHtml(profile,size='normal'){const name=String(profile?.name||'Student').trim(),initials=name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'EP';return profile?.avatar?`<img class="profileAvatar ${size}" src="${profile.avatar}" alt="${esc(name)} profile picture">`:`<div class="profileAvatar fallback ${size}" aria-label="${esc(name)} initials">${esc(initials)}</div>`}
function gatewayEndpoint(){return String(C.syncEndpoint||C.aiEndpoint||'').trim()}
function gatewayJsonp(params){return new Promise((resolve,reject)=>{const endpoint=gatewayEndpoint();if(!endpoint)return reject(new Error('Gateway is not configured.'));if(!navigator.onLine)return reject(new Error('Connect to the internet first.'));const cb='epGW_'+Date.now()+'_'+Math.random().toString(36).slice(2),script=document.createElement('script');let done=false;const cleanup=()=>{if(done)return;done=true;clearTimeout(to);try{delete window[cb]}catch(e){window[cb]=undefined}script.remove()};window[cb]=data=>{cleanup();resolve(data)};script.onerror=()=>{cleanup();reject(new Error('The Gateway could not be reached.'))};const q=new URLSearchParams({...params,prefix:cb});script.src=endpoint+(endpoint.includes('?')?'&':'?')+q.toString();script.async=true;document.body.appendChild(script);const to=setTimeout(()=>{cleanup();reject(new Error('The Gateway request timed out.'))},45000)})}
async function sha256Hex(text){const bytes=new TextEncoder().encode(text),buf=await crypto.subtle.digest('SHA-256',bytes);return[...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function syncAuth(email,pin){return sha256Hex(`EnglishPathways|${String(email).trim().toLowerCase()}|${String(pin)}`)}
function cloudBundle(){let placement=null;try{placement=JSON.parse(localStorage.getItem('english-placement-test-state-v2')||'null')}catch(e){}const cleanState=JSON.parse(JSON.stringify(state));if(cleanState.sync)cleanState.sync={...cleanState.sync,auth:''};const cloudWarnings=[];const placementAudio=placement&&Object.values(placement.responses||{}).filter(r=>r&&r.recorded).length;if(placementAudio)cloudWarnings.push(`${placementAudio} placement speaking recording(s) remain on the original device; audio is not included in cloud sync yet.`);return{formatVersion:2,courseVersion:D.version,savedAt:new Date().toISOString(),state:cleanState,placement,audioIncluded:false,cloudWarnings}}
async function postGateway(payload){const endpoint=gatewayEndpoint();if(!endpoint)throw Error('Gateway is not configured.');await fetch(endpoint,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload)})}
async function waitGatewayResult(requestId,tries=35){for(let i=0;i<tries;i++){await new Promise(r=>setTimeout(r,i<3?900:1300));const r=await gatewayJsonp({action:'result',requestId});if(r?.status==='ready')return r.result;if(r?.status==='error')throw Error(r.error||'Gateway task failed.')}throw Error('The Gateway did not return a result in time.')}
async function cloudSave(showMessage=true){if(!state.sync?.enabled||!state.sync?.email||!state.sync?.auth)throw Error('Connect cloud sync from the Student profile first.');const requestId='sync_'+Date.now()+'_'+Math.random().toString(36).slice(2);state.sync.lastStatus='Syncing…';localStorage.setItem(SKEY,JSON.stringify(state));await postGateway({action:'syncSave',requestId,email:state.sync.email,auth:state.sync.auth,data:JSON.stringify(cloudBundle())});const result=await waitGatewayResult(requestId);if(!result?.ok)throw Error(result?.error||'Cloud save failed.');state.sync.lastSyncAt=new Date().toISOString();state.sync.lastStatus='Synced';localStorage.setItem(SKEY,JSON.stringify(state));if(showMessage)say('Progress synced securely.');return result}
function queueCloudSync(){clearTimeout(syncDebounce);syncDebounce=setTimeout(()=>cloudSave(false).catch(()=>{state.sync.lastStatus='Sync pending';localStorage.setItem(SKEY,JSON.stringify(state))}),9000)}
async function restoreCloudAccount(email,pin){const auth=await syncAuth(email,pin),res=await gatewayJsonp({action:'syncLoad',email:String(email).trim().toLowerCase(),auth});if(!res?.ok)throw Error(res?.error||'No matching cloud profile was found.');const data=typeof res.data==='string'?JSON.parse(res.data):res.data;if(!data?.state)throw Error('The cloud profile is incomplete.');const current=localStorage.getItem(SKEY);if(current)localStorage.setItem(SKEY+'-before-cloud-restore',current);const placementCurrent=localStorage.getItem('english-placement-test-state-v2');if(placementCurrent)localStorage.setItem('english-placement-test-state-v2-before-cloud-restore',placementCurrent);syncSuspend=true;const base=fresh();state={...base,...data.state,profile:{...base.profile,...(data.state.profile||{})},sync:{...base.sync,...(data.state.sync||{}),enabled:true,email:String(email).trim().toLowerCase(),auth,lastSyncAt:new Date().toISOString(),lastStatus:Array.isArray(data.cloudWarnings)&&data.cloudWarnings.length?'Restored — audio stays on original device':'Restored'}};localStorage.setItem(SKEY,JSON.stringify(state));localStorage.setItem('ep-sound-effects',state.soundEffects===false?'off':'on');if(data.placement)localStorage.setItem('english-placement-test-state-v2',JSON.stringify(data.placement));syncSuspend=false;selection=state.level||'A1';return data}
async function connectCloud(email,pin){email=String(email).trim().toLowerCase();if(!email||pin.length<6)throw Error('Use a valid email and a PIN of at least 6 characters.');const auth=await syncAuth(email,pin);state.sync={...state.sync,enabled:true,email,auth,lastStatus:'Connecting…'};localStorage.setItem(SKEY,JSON.stringify(state));try{await cloudSave(false);state.sync.lastStatus='Synced';state.sync.lastSyncAt=new Date().toISOString();localStorage.setItem(SKEY,JSON.stringify(state));return true}catch(err){state.sync={...state.sync,enabled:false,auth:'',lastStatus:'Not connected'};localStorage.setItem(SKEY,JSON.stringify(state));throw err}}
async function fileToAvatar(file){if(!file)return'';if(!/^image\//.test(file.type))throw Error('Choose an image file.');const data=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>no(r.error);r.readAsDataURL(file)});const img=await new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=no;i.src=data});const max=320,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);return canvas.toDataURL('image/jpeg',.82)}
function profileView(){announceView('profile');const syncReady=Boolean(gatewayEndpoint()),connected=Boolean(state.sync?.enabled&&state.sync?.auth);screen.innerHTML=`<div class="shell"><section class="hero profileHero"><div class="profileHeroRow">${avatarHtml(state.profile,'large')}<div><div class="eyebrow">Student profile</div><h1>${esc(state.profile.name||'Your learner profile')}</h1><p class="lead">Your information, learning preferences and cross-device progress.</p></div></div></section><section class="card" style="margin-top:16px"><div class="profileEditor"><div class="avatarEditor">${avatarHtml(state.profile,'xlarge')}<label class="secondary fileButton">Choose picture<input id="profilePhoto" type="file" accept="image/*" hidden></label><button class="ghost" id="removePhoto" ${state.profile.avatar?'':'disabled'}>Remove picture</button></div><div class="formgrid"><div class="field"><label>Name</label><input id="profileName" value="${esc(state.profile.name)}"></div><div class="field"><label>Email</label><input id="profileEmail" type="email" value="${esc(state.profile.email)}"></div><div class="field"><label>Country / location</label><input id="profileCountry" value="${esc(state.profile.country||'')}" placeholder="Optional"></div><div class="field"><label>First language</label><input id="profileLanguage" value="${esc(state.profile.nativeLanguage||'')}" placeholder="Optional"></div><div class="field"><label>Main purpose</label><select id="profilePurpose">${['General English','Employment','Teaching','Academic study','Travel','Examinations'].map(v=>`<option ${state.profile.purpose===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>English preference</label><select id="profileEnglish"><option ${state.profile.englishPreference==='British English'?'selected':''}>British English</option><option ${state.profile.englishPreference==='American English'?'selected':''}>American English</option><option ${state.profile.englishPreference==='International English'?'selected':''}>International English</option></select></div><div class="field full"><label>Learning goal</label><input id="profileGoal" value="${esc(state.profile.goal||'')}" placeholder="Example: speak confidently at work"></div><div class="field full"><label>Interests</label><input id="profileInterests" value="${esc(state.profile.interests||'')}" placeholder="Example: travel, technology, business, movies"></div><div class="field"><label>Daily study target</label><select id="profileMinutes">${[15,20,30,45,60].map(n=>`<option value="${n}" ${Number(state.profile.dailyMinutes||30)===n?'selected':''}>${n} minutes</option>`).join('')}</select></div><div class="field"><label>Answer sounds</label><select id="profileSounds"><option value="on" ${state.soundEffects===false?'':'selected'}>On</option><option value="off" ${state.soundEffects===false?'selected':''}>Off</option></select></div><div class="full buttons"><button class="primary" id="saveProfile">Save profile</button></div></div></div></section><section class="card cloudCard" style="margin-top:16px"><div class="cloudHeading"><div><div class="eyebrow">Cross-device restore</div><h2>Cloud sync</h2></div><span class="syncStatus ${connected?'connected':''}">${connected?'Connected':'Not connected'}</span></div><p>Use the same email and a private PIN on another phone, tablet or computer. The PIN protects the account; email alone would be unsafe.</p>${syncReady?`<div class="formgrid"><div class="field"><label>Account email</label><input id="syncEmail" type="email" value="${esc(state.sync?.email||state.profile.email||'')}"></div><div class="field"><label>Private sync PIN</label><input id="syncPin" type="password" inputmode="numeric" placeholder="6 or more characters"></div></div><div class="buttons"><button class="primary" id="connectSync">${connected?'Update cloud copy':'Connect & save to cloud'}</button><button class="secondary" id="syncNow" ${connected?'':'disabled'}>Sync now</button><button class="ghost" id="restoreNow">Restore from cloud</button></div><div class="notice" style="margin-top:12px">Profile, course progress and placement-test state are synced. Audio recordings remain on the device in this version.</div>`:`<div class="notice warn">Deploy the included English Pathways Gateway v2 to enable secure cross-device restore.</div>`}</section><section class="card" style="margin-top:16px"><h2>Placement progress transfer</h2><p>Manual transfer remains available as a backup even when cloud sync is enabled.</p><div class="buttons"><button class="secondary" id="profilePlacementExport" ${localStorage.getItem('english-placement-test-state-v2')?'':'disabled'}>Export placement progress</button><label class="ghost fileButton">Import placement progress<input id="profilePlacementFile" type="file" accept=".json,application/json" hidden></label></div></section></div>`;$('profilePhoto').onchange=async e=>{try{state.profile.avatar=await fileToAvatar(e.target.files[0]);save();profileView()}catch(err){say(err.message||err)}};$('removePhoto').onclick=()=>{state.profile.avatar='';save();profileView()};$('saveProfile').onclick=()=>{const oldEmail=state.profile.email;state.profile={...state.profile,name:$('profileName').value.trim(),email:$('profileEmail').value.trim(),country:$('profileCountry').value.trim(),nativeLanguage:$('profileLanguage').value.trim(),purpose:$('profilePurpose').value,englishPreference:$('profileEnglish').value,goal:$('profileGoal').value.trim(),interests:$('profileInterests').value.trim(),dailyMinutes:Number($('profileMinutes').value)};state.soundEffects=$('profileSounds').value==='on';if(oldEmail&&state.profile.email!==oldEmail&&state.sync?.enabled)state.sync={...state.sync,enabled:false,auth:'',email:'',lastStatus:'Reconnect after email change'};save();soundFx('tap');say('Profile saved.');profileView()};$('profilePlacementExport').onclick=exportPlacementProgress;$('profilePlacementFile').onchange=e=>importPlacementProgress(e.target.files[0]);if(syncReady){$('connectSync').onclick=async()=>{const b=$('connectSync');b.disabled=true;const old=b.textContent;b.textContent='Connecting…';try{const email=$('syncEmail').value.trim(),pin=$('syncPin').value;state.profile.email=email;await connectCloud(email,pin);say('Cloud sync connected.');profileView()}catch(err){say('Cloud sync failed: '+(err.message||err));b.disabled=false;b.textContent=old}};$('syncNow').onclick=async()=>{try{$('syncNow').disabled=true;await cloudSave(true);profileView()}catch(err){say('Sync failed: '+(err.message||err));$('syncNow').disabled=false}};$('restoreNow').onclick=async()=>{const email=$('syncEmail').value.trim(),pin=$('syncPin').value;if(!email||pin.length<6)return say('Enter the account email and PIN first.');try{await restoreCloudAccount(email,pin);say('Cloud progress restored.');profileView()}catch(err){say('Restore failed: '+(err.message||err))}}}}
function soundFx(kind='tap'){if(state.soundEffects===false||localStorage.getItem('ep-sound-effects')==='off')return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const c=soundFx.ctx||(soundFx.ctx=new AC());if(c.state==='suspended')c.resume();const now=c.currentTime,notes=kind==='good'?[[660,.06,0],[880,.08,.08]]:kind==='bad'?[[310,.055,0],[245,.07,.07]]:[[560,.035,0]];for(const[n,d,off]of notes){const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(n,now+off);g.gain.setValueAtTime(.0001,now+off);g.gain.exponentialRampToValueAtTime(.035,now+off+.008);g.gain.exponentialRampToValueAtTime(.0001,now+off+d);o.connect(g);g.connect(c.destination);o.start(now+off);o.stop(now+off+d+.01)}}catch(e){}}
function blobBase64(blob){return new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]||'');r.onerror=()=>no(r.error);r.readAsDataURL(blob)})}
async function gradeVoiceBlob(blob,context={}){if(blob.size>4.5*1024*1024)throw Error('This recording is too large for instant AI checking. Record a shorter answer.');const requestId='voice_'+Date.now()+'_'+Math.random().toString(36).slice(2),audioBase64=await blobBase64(blob);await postGateway({action:'gradeVoice',requestId,level:context.level||state.level,skill:context.skill||'Speaking',task:context.task||'',focus:context.focus||'',mimeType:blob.type||'audio/webm',audioBase64,formalAssessment:Boolean(context.formalAssessment)});const result=await waitGatewayResult(requestId,45);if(!result?.ok)throw Error(result?.error||'Voice grading failed.');return result.grading||result}
function voiceFeedbackHtml(g){const r=g.result==='correct'?'Strong response':g.result==='partly_correct'?'Good start — improve':'Needs another try',cls=g.result==='correct'?'good':g.result==='partly_correct'?'partial':'bad';return`<div class="aiResult ${cls}"><div class="aiResultHead"><strong>${r}</strong>${Number.isFinite(Number(g.score))?`<span class="aiScore">${esc(g.score)}/${esc(g.maxScore||5)}</span>`:''}</div>${g.transcript?`<p><b>What the AI heard:</b> ${esc(g.transcript)}</p>`:''}${g.taskAchievement?`<p><b>Task:</b> ${esc(g.taskAchievement)}</p>`:''}${g.fluency?`<p><b>Fluency:</b> ${esc(g.fluency)}</p>`:''}${g.pronunciation?`<p><b>Intelligibility / pronunciation:</b> ${esc(g.pronunciation)}</p>`:''}${g.languageFeedback?`<p><b>Grammar & vocabulary:</b> ${esc(g.languageFeedback)}</p>`:''}${g.feedback?`<p><b>Next step:</b> ${esc(g.feedback)}</p>`:''}<p class="aiHint"><small>AI audio feedback is an educational estimate. It does not measure individual phonemes with laboratory precision.</small></p></div>`}
function moreView(){announceView('more');const l=level(state.level),hasPlacement=Boolean(localStorage.getItem('english-placement-test-state-v2')),installed=Boolean(window.EnglishPathwaysMobile?.isInstalled?.());screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Tools and settings</div><h1>More</h1><p class="lead">Assessment, profile, transfer, updates and help.</p></section><section class="card" style="margin-top:14px"><div class="mobileActionGrid"><button class="mobileActionCard primaryCard" id="moreProfile"><b>Student profile & cloud sync</b><small>Add a picture and learner information, or restore progress on another device.</small></button><button class="mobileActionCard primaryCard" id="moreExam"><b>${esc(l.cefr)} end-of-level exam</b><small>Timed objective section, writing and recorded speaking.</small></button><button class="mobileActionCard" id="morePlacement"><b>Placement test</b><small>Open the comprehensive placement assessment.</small></button><button class="mobileActionCard" id="morePlacementExport" ${hasPlacement?'':'disabled'}><b>Export placement progress</b><small>${hasPlacement?'Save the current placement-test answers and position to a transfer file.':'No saved placement-test progress was found on this device.'}</small></button><button class="mobileActionCard" id="morePlacementImport"><b>Import placement progress</b><small>Restore a placement-progress file from another computer or phone.</small></button><input id="placementProgressFile" type="file" accept=".json,application/json" hidden><button class="mobileActionCard" id="moreUpdates"><b>Course updates</b><small>Install an official lesson content pack.</small></button>${installed?'':`<button class="mobileActionCard" id="moreInstall"><b>Install this app</b><small>Add English Pathways to the phone Home Screen.</small></button>`}<button class="mobileActionCard" id="moreTheme"><b>Appearance</b><small>Switch between light and dark mode.</small></button><button class="mobileActionCard" id="moreSound"><b>Answer sounds: ${state.soundEffects===false?'Off':'On'}</b><small>Use short neutral and feedback tones. Formal tests never reveal correctness while active.</small></button><button class="mobileActionCard" id="moreGuide"><b>Arabic student guide</b><small>Open the Arabic operating guide included with the app.</small></button></div></section><section class="card" style="margin-top:14px"><h2>About this edition</h2><p>Mobile App Edition 4.1 • Course ${esc(D.version)} • ${D.lessonCount} lessons.</p><div class="notice">Manual placement transfer works on desktop and mobile. Cloud sync adds cross-device restore after Gateway v2 is deployed.</div></section></div>`;$('moreProfile').onclick=()=>go('profile');$('moreExam').onclick=()=>go('exam',{level:state.level});$('morePlacement').onclick=()=>window.open('placement-test/index.html','_blank');$('morePlacementExport').onclick=exportPlacementProgress;$('morePlacementImport').onclick=()=>$('placementProgressFile').click();$('placementProgressFile').onchange=e=>importPlacementProgress(e.target.files[0]);$('moreUpdates').onclick=()=>go('updates');$('moreInstall')&&($('moreInstall').onclick=()=>window.EnglishPathwaysMobile?.installApp?.());$('moreTheme').onclick=()=>{$('themeBtn')?.click();moreView()};$('moreSound').onclick=()=>{state.soundEffects=state.soundEffects===false?true:false;save();soundFx('tap');moreView()};$('moreGuide').onclick=()=>window.open('دليل_الطالب_بالعربية.html','_blank')}
function updatesView(){announceView('more');const packs=contentPacks();screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Course content manager</div><h1>Install lesson updates</h1><p class="lead">Future course packs can add units, lessons and dictionary entries without deleting completed work.</p><div class="metrics"><div class="metric"><small>Application version</small><strong>${esc(C.version)}</strong></div><div class="metric"><small>Course version</small><strong>${esc(D.version)}</strong></div><div class="metric"><small>Available lessons</small><strong>${D.lessonCount}</strong></div><div class="metric"><small>Installed packs</small><strong>${packs.length}</strong></div></div><div class="notice warn"><b>Before installing:</b> export a progress backup. Only install official English Pathways JSON content packs supplied by the teacher.</div><div class="field" style="margin-top:18px"><label>Course content pack (.json)</label><input id="contentPackFile" type="file" accept=".json"></div><div class="buttons"><button class="primary" id="installPack">Install selected update</button><button class="secondary" id="exportBeforeUpdate">Export backup first</button><button class="ghost" id="returnAfterUpdate">Return to dashboard</button></div></section><section class="card" style="margin-top:16px"><h2>Installed content packs</h2>${packs.length?packs.map(p=>`<div class="lessonRow"><div class="num">✓</div><div><b>${esc(p.title||p.contentPackVersion)}</b><br><small>${esc(p.contentPackVersion||'Unknown version')} • ${esc(p.installedAt||'Installed')}</small></div><span>Active</span></div>`).join(''):'<div class="notice" style="margin-top:14px">No separate update packs are installed. Version 4.1 includes the refined premium lesson experience across the core curriculum.</div>'}<p><small>Updates add content; they do not overwrite existing answers or completed-lesson records. Removing a pack is intentionally unavailable because it could hide lessons that contain student work.</small></p></section></div>`;$('installPack').onclick=()=>installContentPack($('contentPackFile').files[0]);$('exportBeforeUpdate').onclick=exportBackup;$('returnAfterUpdate').onclick=dashboard}
async function installContentPack(f){if(!f)return say('Select a JSON content pack first.');try{const pack=JSON.parse(await f.text());if(pack.platform!=='English Pathways'||!pack.contentPackVersion||(!Array.isArray(pack.addedUnits)&&!Array.isArray(pack.replaceUnits)))throw Error('This is not a recognised English Pathways content pack.');if(pack.minimumAppVersion&&compareVersions(C.version,pack.minimumAppVersion)<0)throw Error('This pack requires application version '+pack.minimumAppVersion+' or later.');const packs=contentPacks();if(packs.some(p=>p.contentPackVersion===pack.contentPackVersion))throw Error('This content pack is already installed.');pack.installedAt=new Date().toISOString();packs.push(pack);localStorage.setItem(PACKKEY,JSON.stringify(packs));applyContentPacks();log('content-pack-installed',{version:pack.contentPackVersion,title:pack.title||''});say('Content update installed.');setTimeout(updatesView,400)}catch(e){say('Update failed: '+e.message)}}
function gate(){if(admin)return go('admin');modal.innerHTML=`<div class="backdrop"><div class="modalBox"><div class="eyebrow">Administrator</div><h2>Enter password</h2><div class="field"><input id="pass" type="password"></div><div class="buttons"><button class="ghost" id="cancel">Cancel</button><button class="primary" id="unlock">Open admin</button></div><p><small>This is a local convenience gate, not strong server security. Change the password in config.js.</small></p></div></div>`;$('cancel').onclick=()=>modal.innerHTML='';$('unlock').onclick=()=>{if($('pass').value===C.adminPassword){admin=true;modal.innerHTML='';go('admin')}else say('Incorrect password.')}}

const PLACEMENT_STATE_KEY='english-placement-test-state-v2';
function exportPlacementProgress(){
  try{
    const raw=localStorage.getItem(PLACEMENT_STATE_KEY);
    if(!raw)throw new Error('No saved placement-test progress was found on this device.');
    const placementState=JSON.parse(raw);
    const payload={type:'english-pathways-placement-progress',formatVersion:1,exportedAt:new Date().toISOString(),courseVersion:D.version,placementState};
    const candidate=placementState?.candidate?.name||state.profile.name||'student';
    download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),safe(candidate)+'_Placement_Progress.json');
    say('Placement progress exported.');
  }catch(e){say('Export failed: '+e.message)}
}
async function importPlacementProgress(file){
  if(!file)return;
  try{
    const payload=JSON.parse(await file.text());
    const imported=payload?.type==='english-pathways-placement-progress'?payload.placementState:(payload?.placementState||payload);
    if(!imported||typeof imported!=='object'||typeof imported.started!=='boolean'||!imported.responses||typeof imported.responses!=='object')throw new Error('This is not a recognised placement-progress file.');
    const current=localStorage.getItem(PLACEMENT_STATE_KEY);
    if(current)localStorage.setItem(PLACEMENT_STATE_KEY+'-before-import',current);
    const restored={...imported};
    if(!restored.finished){restored.paused=false;restored.viewingResultsSectionIndex=null}
    localStorage.setItem(PLACEMENT_STATE_KEY,JSON.stringify(restored));
    say('Placement progress imported. Opening the test…');
    setTimeout(()=>window.open('placement-test/index.html','_self'),500);
  }catch(e){say('Import failed: '+e.message)}
}
function adminView(tab='overview'){if(!admin)return gate();screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Teacher and administrator</div><h1>Administration</h1><p class="lead">Manage levels, placement import, teacher submission, data and reusable AI prompts.</p></section><section class="card" style="margin-top:16px"><div class="adminTabs">${['overview','levels','submission','prompts','data'].map(t=>`<button data-tab="${t}" class="${t===tab?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="adminContent">${adminHtml(tab)}</div></section></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>adminView(b.dataset.tab));bindAdmin(tab)}
function adminHtml(t){if(t==='overview')return`<div class="grid2"><div class="notice"><h3>Placement result import</h3><p>Import JSON or the placement-test ZIP. The recommendation is provisional until writing and speaking are reviewed.</p><input id="placementFile" type="file" accept=".json,.zip"><div id="placementStatus"></div></div><div class="notice"><h3>Current recommendation</h3><p>${state.recommendation?esc(state.recommendation):'None imported.'}</p><button class="secondary" id="applyRec" ${state.recommendation?'':'disabled'}>Apply recommendation</button></div></div>`;if(t==='levels')return`${D.levels.map(l=>`<div class="lessonRow"><div class="num">${l.cefr}</div><div><b>${esc(l.name)}</b><br><small>${prog(l.id).p}% complete</small></div><label><input type="checkbox" data-unlock="${l.id}" ${unlocked(l.id)?'checked':''}> Unlocked</label></div>`).join('')}<div class="field" style="margin-top:15px"><label>Current level</label><select id="currentLevel">${D.levels.map(l=>`<option value="${l.id}" ${state.level===l.id?'selected':''}>${l.cefr} — ${esc(l.name)}</option>`).join('')}</select></div>`;if(t==='submission')return`<h2>Teacher email submission</h2><p>Deploy the included Google Apps Script and paste its Web App URL.</p><div class="field"><label>Web App URL</label><input id="endpoint" value="${esc(state.endpoint)}"></div><div class="buttons"><button class="primary" id="saveEndpoint">Save</button></div><div class="notice warn" style="margin-top:15px">Large audio packages may exceed free service limits. ZIP download remains the backup.</div>`;if(t==='prompts')return`<h2>AI prompt library</h2><p>Upload the relevant ZIP to a new ChatGPT conversation, then copy the matching prompt.</p>${Object.entries(P).map(([n,x],i)=>`<div class="promptCard"><h3>${esc(n)}</h3><pre>${esc(x)}</pre><button class="secondary" data-copy="${i}">Copy prompt</button></div>`).join('')}`;return`<div class="grid2"><div class="notice"><h3>Backup and restore</h3><div class="buttons"><button class="primary" id="exportAll">Export backup</button><label class="secondary"><input id="restore" type="file" accept=".zip,.json" hidden>Restore backup</label></div></div><div class="notice warn"><h3>Reset</h3><button class="danger" id="reset">Delete all local progress</button></div></div>`}
function bindAdmin(t){if(t==='overview'){$('placementFile').onchange=e=>importPlacement(e.target.files[0]);$('applyRec').onclick=()=>{const l=D.levels.find(x=>x.id===state.recommendation);if(l){state.level=l.id;state.unlocked=D.levels.slice(0,idx(l.id)+1).map(x=>x.id);state.current=l.units[0].lessons[0].id;save();say('Recommendation applied.')}}}if(t==='levels'){document.querySelectorAll('[data-unlock]').forEach(c=>c.onchange=()=>{c.checked&&!unlocked(c.dataset.unlock)?state.unlocked.push(c.dataset.unlock):!c.checked&&(state.unlocked=state.unlocked.filter(x=>x!==c.dataset.unlock));save()});$('currentLevel').onchange=()=>{state.level=$('currentLevel').value;if(!unlocked(state.level))state.unlocked.push(state.level);state.current=level(state.level).units[0].lessons[0].id;save();say('Current level changed.')}}if(t==='submission')$('saveEndpoint').onclick=()=>{state.endpoint=$('endpoint').value.trim();save();say('Endpoint saved.')};if(t==='prompts'){const a=Object.values(P);document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText(a[Number(b.dataset.copy)]);say('Prompt copied.')} )}if(t==='data'){$('exportAll').onclick=exportBackup;$('restore').onchange=e=>restoreBackup(e.target.files[0]);$('reset').onclick=()=>{if(confirm('Delete all local progress?')){localStorage.removeItem(SKEY);localStorage.removeItem(PACKKEY);indexedDB.deleteDatabase(DB);state=fresh();admin=false;render()}}}}
async function importPlacement(f){if(!f)return;try{let d;if(f.name.endsWith('.zip')){const z=await JSZip.loadAsync(f);let target;z.forEach((p,o)=>{if(/(results_with_answer_key|answers_with_key|completed_responses|responses)\.json$/.test(p))target=o});if(!target)throw Error('No recognised results JSON');d=JSON.parse(await target.async('text'))}else d=JSON.parse(await f.text());const s=[];(d.sections||[]).forEach(x=>{if(x.score&&Number.isFinite(Number(x.score.percentage)))s.push(Number(x.score.percentage))});if(!s.length)throw Error('No objective scores');const a=s.reduce((x,y)=>x+y,0)/s.length;state.recommendation=a<30?'A1':a<45?'A2':a<60?'B1':a<72?'B2_1':a<82?'B2_2':a<90?'C1_1':'C1_2';save();$('placementStatus').innerHTML=`<p>Objective average: <b>${Math.round(a)}%</b>. Provisional recommendation: <b>${level(state.recommendation).cefr} — ${esc(level(state.recommendation).name)}</b>.</p>`}catch(e){$('placementStatus').textContent='Import failed: '+e.message}}
function audioExt(b){const t=(b?.type||'').toLowerCase();if(t.includes('mp4')||t.includes('m4a'))return'.m4a';if(t.includes('ogg'))return'.ogg';if(t.includes('wav'))return'.wav';return'.webm'}async function packageZip(kind='progress',id=null){const z=new JSZip(),payload={platform:{title:D.title,version:D.version,appVersion:C.version,mobileEdition:C.mobileEdition||null},kind,exportedAt:new Date().toISOString(),state,contentPacks:contentPacks()};if(kind==='exam')payload.exam=state.exams[id];z.file('progress.json',JSON.stringify(payload,null,2));z.file('AI_REVIEW_PROMPT.txt',kind==='exam'?P['End-of-level exam grading prompt']:P['Course-progress review prompt']);z.file('README.txt','Upload this ZIP to ChatGPT and paste AI_REVIEW_PROMPT.txt. Audio may be WebM, M4A, OGG or WAV depending on the phone/browser.');const rf=z.folder('recordings'),all=await keys(),wanted=kind==='exam'&&state.exams[id]?.speakingKey?[state.exams[id].speakingKey]:all;for(const k of wanted){const b=await get(k);if(b)rf.file(safe(k)+audioExt(b),b)}return z}async function exportBackup(){say('Preparing backup…');const z=await packageZip();download(await z.generateAsync({type:'blob',compression:'DEFLATE'}),safe(state.profile.name)+'_English_Pathways_Backup.zip');say('Backup downloaded.')}async function exportPackage(k,id){say('Preparing exam package…');const z=await packageZip(k,id);download(await z.generateAsync({type:'blob',compression:'DEFLATE'}),safe(state.profile.name)+'_'+id+'_Exam.zip')}
async function restoreBackup(f){if(!f)return;try{let d;if(f.name.endsWith('.zip')){const z=await JSZip.loadAsync(f),p=z.file('progress.json');if(!p)throw Error('progress.json not found');d=JSON.parse(await p.async('text'))}else d=JSON.parse(await f.text());state={...fresh(),...(d.state||d)};if(Array.isArray(d.contentPacks))localStorage.setItem(PACKKEY,JSON.stringify(d.contentPacks));save();say('Backup restored. Reloading course content…');setTimeout(()=>location.reload(),500)}catch(e){say('Restore failed: '+e.message)}}
async function sendTeacher(kind,id){if(!state.endpoint)return say('Teacher submission is not configured. Download the ZIP instead.');if(!navigator.onLine)return say('You are offline. Connect to the internet, then submit again.');try{say('Preparing and uploading submission…');const z=await packageZip(kind,id),b64=await z.generateAsync({type:'base64'}),stamp=new Date().toISOString().replace(/[:.]/g,'-'),payload={studentName:state.profile.name,studentEmail:state.profile.email,kind,level:id||state.level,filename:safe(state.profile.name)+'_'+(id||state.level)+'_'+kind+'_'+stamp+'.zip',fileBase64:b64};await fetch(state.endpoint,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify(payload)});say('Submission sent. Keep the downloaded ZIP until the teacher confirms receipt.')}catch(e){say('Submission failed. Download the ZIP and send it manually.')}}
window.EnglishPathways={go,openDictionary,exportBackup,restoreBackup,sendTeacher,say,cloudSave,exportPlacementProgress,importPlacementProgress,soundFx,getState:()=>state};render();})();
